def fertility_table(encoders, parallel, ref='eng_Latn'):
    """Per encoder and language: passages, UTF-8 bytes, tokens, bytes per
    token, tokens per passage, the share of byte-fallback tokens and the
    premium, the tokens a language needs over the tokens ref needs for
    translations of the same passages. encoders maps a name to encode(str)
    -> ids, or to (encode, fallback_ids); parallel maps a language to its
    passages, aligned across languages.

    Defined in :numref:`sec_lm_tokenizers`"""
    rows = []
    for name, enc in encoders.items():
        enc, fallback = enc if isinstance(enc, tuple) else (enc, ())
        fallback = set(fallback)
        for lang, passages in parallel.items():
            ids = [enc(p) for p in passages]
            n = sum(map(len, ids))
            n_bytes = sum(len(p.encode('utf-8')) for p in passages)
            rows.append(dict(
                encoder=name, lang=lang, passages=len(passages),
                bytes=n_bytes, tokens=n, bytes_per_token=n_bytes / n,
                tokens_per_passage=n / len(passages),
                fallback_share=sum(i in fallback for x in ids for i in x)
                / n))
    df = pd.DataFrame(rows)
    ref_tokens = df[df.lang == ref].set_index('encoder').tokens
    df['premium'] = df.tokens / df.encoder.map(ref_tokens)
    return df

def _unigram_lattice(s, logp, max_len):
    """Edges (i, j, piece) of the segmentation lattice of s, by start i:
    s[i:j] is a piece of logp.

    Defined in :numref:`sec_lm_tokenizers`"""
    return [(i, j, s[i:j]) for i in range(len(s))
            for j in range(i + 1, min(len(s), i + max_len) + 1)
            if s[i:j] in logp]

def _unigram_fb(s, logp, max_len):
    """log P(s), summed over all segmentations of s, and each piece's
    posterior expected count in s (forward-backward on the lattice).

    Defined in :numref:`sec_lm_tokenizers`"""
    n, edges = len(s), _unigram_lattice(s, logp, max_len)
    fwd, bwd = [-math.inf] * (n + 1), [-math.inf] * (n + 1)
    fwd[0] = bwd[n] = 0.0
    for i, j, x in edges:  # by start: fwd[i] is complete when read
        fwd[j] = d2l._logaddexp(fwd[j], fwd[i] + logp[x])
    for i, j, x in reversed(edges):  # by start, descending
        bwd[i] = d2l._logaddexp(bwd[i], logp[x] + bwd[j])
    counts = collections.Counter()
    for i, j, x in edges:
        counts[x] += math.exp(fwd[i] + logp[x] + bwd[j] - fwd[n])
    return fwd[n], counts

def viterbi_segment(text, logp, max_len, *, unk=None):
    """The most probable segmentation of text into pieces of logp (piece
    -> log-probability) of at most max_len characters; ties go to fewer
    pieces. With unk, a character that is no piece is a piece of
    log-probability unk (SentencePiece's rule for unknown characters).

    Defined in :numref:`sec_lm_tokenizers`"""
    n = len(text)
    best, back = [(-math.inf, 0)] * (n + 1), [0] * (n + 1)
    best[0] = (0.0, 0)  # (log-probability, minus the number of pieces)
    for j in range(1, n + 1):
        for i in range(max(0, j - max_len), j):
            lp = logp.get(text[i:j], unk if j == i + 1 else None)
            if lp is not None and best[i][0] > -math.inf:
                cand = (best[i][0] + lp, best[i][1] - 1)
                if cand > best[j]:
                    best[j], back[j] = cand, i
    if best[n][0] == -math.inf:
        raise ValueError(f'no segmentation of {text!r}')
    out, j = [], n
    while j > 0:
        out.append(text[back[j]:j])
        j = back[j]
    return out[::-1]

def _unigram_sample(s, logp, max_len, alpha, rng):
    """A segmentation of s drawn with probability proportional to
    P(segmentation)^alpha: forward filtering, then backward sampling.

    Defined in :numref:`sec_lm_tokenizers`"""
    fwd, into = [-math.inf] * (len(s) + 1), collections.defaultdict(list)
    fwd[0] = 0.0
    for i, j, x in _unigram_lattice(s, logp, max_len):
        fwd[j] = d2l._logaddexp(fwd[j], fwd[i] + alpha * logp[x])
        into[j].append((i, x))
    out, j = [], len(s)
    while j > 0:
        w = np.array([fwd[i] + alpha * logp[x] for i, x in into[j]])
        p = np.exp(w - w.max())
        i, x = into[j][rng.choice(len(w), p=p / p.sum())]
        out.append(x)
        j = i
    return out[::-1]

class UnigramTokenizer:
    """A unigram language model over pieces (Kudo 2018), trained by EM
    with pruning: seed the vocabulary with every character and the
    seed_size most frequent substrings (scored by count times length),
    then alternate em_iters EM steps with keeping prune_frac of the pieces
    until vocab_size remain. Words are split at whitespace and marked by a
    leading U+2581, as SentencePiece marks them.

    Defined in :numref:`sec_lm_tokenizers`"""
    def __init__(self, vocab_size, seed_size=100_000, em_iters=2,
                 prune_frac=0.8, max_piece_len=12):
        self.vocab_size, self.seed_size = vocab_size, seed_size
        self.em_iters, self.prune_frac = em_iters, prune_frac
        self.max_len, self.pieces, self.history = max_piece_len, {}, []

    @staticmethod
    def _words(sentences):
        return collections.Counter('▁' + w for s in sentences
                                   for w in s.split())

    def _em_step(self, words, logp):
        """E: expected piece counts under logp; M: probabilities
        proportional to them. Returns the new log-probabilities and the
        corpus log-likelihood under the old ones."""
        counts, loglik = collections.Counter(), 0.0
        for w, c in words.items():
            logz, cw = d2l._unigram_fb(w, logp, self.max_len)
            loglik += c * logz
            for x, v in cw.items():
                counts[x] += c * v
        for x in logp:  # a character stays a piece, however rare
            if len(x) == 1 and counts[x] <= 0:
                counts[x] = 1e-6
        log_total = math.log(sum(counts.values()))
        return ({x: math.log(counts[x]) - log_total for x in logp
                 if counts[x] > 0}, loglik)

    def _prune(self, words, logp, keep):
        """The keep pieces whose removal costs the most likelihood: a
        piece's loss is its count in the Viterbi segmentations times what
        its log-probability gains over the best segmentation of its own
        string without it. Characters are always kept."""
        freq = collections.Counter()
        for w, c in words.items():
            for x in d2l.viterbi_segment(w, logp, self.max_len):
                freq[x] += c
        loss, others = {}, dict(logp)
        for x, lp in logp.items():
            if len(x) > 1:
                del others[x]
                alt = d2l.viterbi_segment(x, others, self.max_len)
                loss[x] = freq[x] * (lp - sum(others[a] for a in alt))
                others[x] = lp
        chars = [x for x in logp if len(x) == 1]
        ranked = sorted(loss, key=lambda x: (-loss[x], x))
        kept = set(chars) | set(ranked[:max(keep - len(chars), 0)])
        return {x: lp for x, lp in logp.items() if x in kept}

    def train(self, sentences):
        words = self._words(sentences)
        subs, chars = collections.Counter(), collections.Counter()
        for w, c in words.items():
            for i in range(len(w)):
                chars[w[i]] += c
                for j in range(i + 2, min(len(w), i + self.max_len) + 1):
                    subs[w[i:j]] += c
        seed = sorted(subs, key=lambda x: (-subs[x] * len(x), x))
        seed = {x: subs[x] * len(x) for x in seed[:self.seed_size]}
        seed.update(chars)
        total = sum(seed.values())
        logp = {x: math.log(v / total) for x, v in seed.items()}
        while True:
            for _ in range(self.em_iters):
                logp, loglik = self._em_step(words, logp)
                self.history.append((len(logp), loglik))
            if len(logp) <= self.vocab_size:
                break
            logp = self._prune(words, logp, max(
                self.vocab_size, int(len(logp) * self.prune_frac)))
        self.pieces = logp
        return self

    def encode(self, text):
        return [x for w in text.split() for x in d2l.viterbi_segment(
            '▁' + w, self.pieces, self.max_len)]

    def encode_sample(self, text, alpha=0.2, seed=0):
        """A segmentation drawn with probability proportional to
        P(segmentation)^alpha, word by word (subword regularization)."""
        rng = np.random.default_rng(seed)
        return [x for w in text.split() for x in d2l._unigram_sample(
            '▁' + w, self.pieces, self.max_len, alpha, rng)]

R2_SPLIT_REGEX = (r"""(?i:'s|'t|'re|'ve|'m|'ll|'d)|[^\r\n\p{L}\p{N}]?\p{L}+"""
                  r"""|\p{N}| ?[^\s\p{L}\p{N}]+[\r\n]*|\s*[\r\n]+|\s+(?!\S)"""
                  r"""|\s+""")

def train_hf_bpe(texts, vocab_size, specials, regex=R2_SPLIT_REGEX,
                 min_frequency=2):
    """A byte-level BPE (Hugging Face tokenizers) trained on texts: NFC,
    the split regex, bytes as 256 base symbols, the special tokens first
    (ids 0, 1, ...), no BOS or EOS added on encode. Special-token strings
    inside a text are encoded as text (encode_special_tokens is set; the
    flag is not saved in tokenizer.json, so loaders set it again).

    Defined in :numref:`sec_lm_tokenizers`"""
    from tokenizers import (Regex, Tokenizer, decoders, models, normalizers,
                            pre_tokenizers, trainers)
    tok = Tokenizer(models.BPE(dropout=None, byte_fallback=False,
                               unk_token=None))
    tok.normalizer = normalizers.NFC()
    tok.pre_tokenizer = pre_tokenizers.Sequence([
        pre_tokenizers.Split(Regex(regex), behavior='isolated', invert=False),
        pre_tokenizers.ByteLevel(add_prefix_space=False, trim_offsets=False,
                                 use_regex=False)])
    tok.decoder = decoders.ByteLevel()
    trainer = trainers.BpeTrainer(
        vocab_size=vocab_size, min_frequency=min_frequency,
        special_tokens=list(specials), show_progress=False,
        initial_alphabet=pre_tokenizers.ByteLevel.alphabet())
    tok.train_from_iterator(texts, trainer=trainer)
    if tok.get_vocab_size() != vocab_size:
        raise ValueError(f'trained {tok.get_vocab_size()} pieces, not '
                         f'{vocab_size}: too little text for this vocabulary')
    tok.encode_special_tokens = True
    return tok

def extend_vocab(model, tokenizer, new_pieces, init='random', seed=0):
    """Add new_pieces to a Transformers tokenizer (as added tokens, which
    are matched before the model's own segmentation) and rows for them to
    the model's input and, if untied, output matrices, initialized by
    init: 'random' (normal, the config's initializer_range), 'mean' (the
    mean of the old rows plus noise of 1% of their standard deviation, so
    that no two rows are equal) or 'decomp' (the mean of the old rows of
    the pieces the old tokenizer splits the new piece into). Returns
    (model, tokenizer) with config.vocab_size updated.

    Defined in :numref:`sec_lm_tokenizers`"""
    if init not in ('random', 'mean', 'decomp'):
        raise ValueError(f'unknown init {init!r}')
    pieces, n_old = list(new_pieces), len(tokenizer)
    parts = tokenizer(pieces, add_special_tokens=False)['input_ids']
    if tokenizer.add_tokens(pieces) != len(pieces):
        raise ValueError('a new piece is in the vocabulary already')
    out = model.get_output_embeddings()
    tied = out is None or out.weight is model.get_input_embeddings().weight
    old = [model.get_input_embeddings().weight] + ([] if tied
                                                   else [out.weight])
    old = [W.detach()[:n_old].float().cpu() for W in old]
    model.resize_token_embeddings(len(tokenizer), mean_resizing=False)
    mats = [model.get_input_embeddings().weight] + (
        [] if tied else [model.get_output_embeddings().weight])
    g = torch.Generator().manual_seed(seed)
    std = model.config.get_text_config().initializer_range
    k, d = len(pieces), old[0].shape[1]
    with torch.no_grad():
        for W, W0 in zip(mats, old):
            if init == 'random':
                new = torch.randn(k, d, generator=g) * std
            elif init == 'mean':
                new = W0.mean(0) + 0.01 * W0.std() * torch.randn(
                    k, d, generator=g)
            else:
                new = torch.stack([W0[ids].mean(0) for ids in parts])
            W[n_old:n_old + k] = new.to(W.device, W.dtype)
    model.config.get_text_config().vocab_size = len(tokenizer)
    return model, tokenizer

R2_TOKENIZER_SHA256 = (  # of lm-r2-tokenizer-v1 (tools/build_r2_shards.py)
    'b1b4b45c36aac256ae4f4bd5e5fd595395242fc6949299cb0e2e25d2a5a656e3')

def r2_tokenizer(raw=False):
    """The reference tokenizer (artifact lm-r2-tokenizer-v1; its file is
    checked against R2_TOKENIZER_SHA256): a Transformers
    PreTrainedTokenizerFast with EOS <|endoftext|> = 0, pad <|pad|> = 1,
    no BOS, and special-token strings in text encoded as text; raw=True
    gives the tokenizers.Tokenizer itself.

    Defined in :numref:`sec_lm_tokenizers`"""
    if 'lm-r2-tokenizer-v1' not in d2l.DATA_HUB or not d2l.R2_TOKENIZER_SHA256:
        raise KeyError('lm-r2-tokenizer-v1 is not registered yet: it is '
                       'built by tools/build_r2_shards.py')
    return d2l._r2_from_file(d2l.download_keyed('lm-r2-tokenizer-v1'),
                             raw=raw, sha256=d2l.R2_TOKENIZER_SHA256)

def write_shards(docs, tokenizer, out_dir, split, shard_tokens=100_000_000,
                 eos_id=None, meta_fn=None, manifest=None, *, batch_docs=1000,
                 max_shards=None):
    """Tokenize documents into shards out_dir/{split}-{k:05d}.bin|.idx|
    .meta.parquet and return the split's manifest entry. docs yields
    (doc_id, text) or (doc_id, text, meta); each document becomes its ids
    and one EOS (eos_id, default the tokenizer's <|endoftext|>); special
    strings in a text stay text, and a special id inside a document is an
    error. A shard closes at the first document boundary at or after
    shard_tokens; ids are uint16 for vocabularies up to 65,536, else uint32.
    meta_fn(doc_id, text, meta) gives a document's extra meta columns
    (default: meta itself). With max_shards, writing stops when that many
    shards are closed (the rest of docs is not read). The entry is stored
    in manifest (a CorpusManifest, created if None), which is saved as
    out_dir/manifest.json.

    Defined in :numref:`sec_lm_tokenizers`"""
    import itertools
    os.makedirs(out_dir, exist_ok=True)
    vocab, eos, special = d2l._tok_info(tokenizer)
    eos = eos if eos_id is None else eos_id
    if eos is None:
        raise ValueError('the tokenizer has no <|endoftext|>: pass eos_id')
    dtype = np.dtype('uint16' if vocab <= 2**16 else 'uint32')
    special = np.array(sorted(special | {eos}), dtype=np.int64)
    shards, w, docs = [], None, iter(docs)
    while (len(shards) != max_shards
           and (batch := list(itertools.islice(docs, batch_docs)))):
        batch = [(d[0], d[1], d[2] if len(d) > 2 else None) for d in batch]
        for (doc_id, text, meta), ids in zip(
                batch, d2l._doc_token_ids(tokenizer, [b[1] for b in batch])):
            ids = np.asarray(ids, dtype=np.int64)
            bad = np.isin(ids, special)
            if bad.any():
                raise ValueError(f'document {doc_id}: special id '
                                 f'{int(ids[bad][0])} inside the text')
            if w is None:
                w = d2l._ShardWriter(out_dir, f'{split}-{len(shards):05d}',
                                     dtype)
            extra = meta_fn(doc_id, text, meta) if meta_fn else (meta or {})
            w.add(doc_id, np.append(ids, eos).astype(dtype), extra)
            if w.n_tokens >= shard_tokens:
                shards.append(w.close())
                w = None
                if len(shards) == max_shards:
                    break
    if w is not None:
        shards.append(w.close())
    entry = dict(n_tokens=sum(s['n_tokens'] for s in shards),
                 n_docs=sum(s['n_docs'] for s in shards), shards=shards)
    manifest = manifest or d2l.CorpusManifest(os.path.basename(
        os.path.normpath(out_dir)))
    manifest.splits = dict(manifest.splits or {}, **{split: entry})
    fmt = dict(dtype=dtype.name, eos_id=int(eos), endianness='little',
               doc_end='eos', idx_dtype='uint32',
               meta_required=['doc_id', 'n_tokens'])
    if manifest.format not in (None, fmt):
        raise ValueError(f'manifest format {manifest.format} != {fmt}')
    manifest.format = fmt
    manifest.tokenizer = manifest.tokenizer or dict(vocab_size=vocab)
    manifest.save(os.path.join(out_dir, 'manifest.json'))
    return entry

class TokenShards:
    """Read-only access to a shard set written by write_shards: documents
    by global index, token ranges by global position, per-shard meta, and
    verify(), which recomputes every file's SHA-256 and the EOS and offset
    invariants. max_tokens keeps the smallest prefix of shards holding at
    least that many tokens; fetch=True downloads missing files from the
    manifest's url and checks sha1 and SHA-256. A pickled copy (a data
    loader's worker) carries no memory maps; it opens its own.

    Defined in :numref:`sec_lm_tokenizers`"""
    def __init__(self, root, split='train', fetch=False, max_tokens=None):
        self.root, self.split, self.fetch = root, split, fetch
        with open(os.path.join(root, 'manifest.json'), encoding='utf-8') as f:
            self.manifest = json.load(f)
        shards = self.manifest['splits'][split]['shards']
        if max_tokens is not None:
            total = np.cumsum([s['n_tokens'] for s in shards])
            shards = shards[:int(np.searchsorted(total, max_tokens)) + 1]
        self.shards = shards
        fmt = self.manifest['format']
        self.dtype = np.dtype(fmt['dtype']).newbyteorder('<')
        self.eos_id = fmt['eos_id']
        self.vocab_size = (self.manifest.get('tokenizer') or {}).get(
            'vocab_size')
        self._docs = np.cumsum([0] + [s['n_docs'] for s in shards])
        self._toks = np.cumsum([0] + [s['n_tokens'] for s in shards])
        self.n_docs, self.n_tokens = int(self._docs[-1]), int(self._toks[-1])
        self.n_shards = len(shards)
        self._mm, self._idx = {}, {}

    def __getstate__(self):  # a worker process reopens the memory maps
        return dict(self.__dict__, _mm={})

    def _path(self, k, ext):
        s = self.shards[k]
        path = os.path.join(self.root, s['file'] + d2l._SHARD_EXT[ext])
        if not os.path.exists(path):
            if not self.fetch or 'url' not in s:
                raise FileNotFoundError(path)
            d2l._fetch_shard_file(s, ext, path)
        return path

    def shard(self, k):
        if k not in self._mm:
            self._mm[k] = np.memmap(self._path(k, 'bin'), dtype=self.dtype,
                                    mode='r')
        return self._mm[k]

    def offsets(self, k):
        if k not in self._idx:
            self._idx[k] = np.fromfile(self._path(k, 'idx'), dtype='<u4')
        return self._idx[k]

    def locate(self, i):
        """(shard, document within it, offset of its first token there)."""
        if not 0 <= i < self.n_docs:
            raise IndexError(i)
        k = int(np.searchsorted(self._docs, i, side='right')) - 1
        j = i - int(self._docs[k])
        return k, j, int(self.offsets(k)[j])

    def locate_token(self, t):
        """(shard, position within it) of global token position t."""
        if not 0 <= t < self.n_tokens:
            raise IndexError(t)
        k = int(np.searchsorted(self._toks, t, side='right')) - 1
        return k, t - int(self._toks[k])

    def doc(self, i):
        k, j, a = self.locate(i)
        return np.asarray(self.shard(k)[a:self.offsets(k)[j + 1]],
                          dtype=np.int32)

    def iter_docs(self, start=0):
        for i in range(start, self.n_docs):
            yield i, self.doc(i)

    def read(self, start, n):
        """n tokens from global position start, across shard boundaries."""
        if start < 0 or start + n > self.n_tokens:
            raise IndexError((start, n))
        out = []
        while n > 0:
            k, a = self.locate_token(start)
            take = min(n, self.shards[k]['n_tokens'] - a)
            out.append(np.asarray(self.shard(k)[a:a + take], dtype=np.int32))
            start, n = start + take, n - take
        return np.concatenate(out) if out else np.zeros(0, dtype=np.int32)

    def meta(self, k):
        return pd.read_parquet(self._path(k, 'meta'))

    def verify(self):
        """Recompute every file's SHA-256 and check that offsets start at 0,
        increase and end at the shard's token count, that EOS ends every
        document and occurs nowhere else, and that the meta rows match."""
        for k, s in enumerate(self.shards):
            for ext in d2l._SHARD_EXT:
                path = self._path(k, ext)
                if d2l._sha256_file(path) != s['sha256'][ext]:
                    raise ValueError(f'{path}: SHA-256 differs from the '
                                     'manifest')
            ids, idx = self.shard(k), self.offsets(k)
            name = s['file']
            if (len(idx) != s['n_docs'] + 1 or idx[0] != 0
                    or idx[-1] != len(ids) or len(ids) != s['n_tokens']
                    or (np.diff(idx.astype(np.int64)) <= 0).any()):
                raise ValueError(f'{name}.idx: offsets do not match the '
                                 'shard')
            if (np.asarray(ids[idx[1:].astype(np.int64) - 1]) != self.eos_id
                    ).any() or int((ids == self.eos_id).sum()) != s['n_docs']:
                raise ValueError(f'{name}.bin: EOS not exactly at the '
                                 'document ends')
            m = self.meta(k)
            if len(m) != s['n_docs'] or (m['n_tokens'].to_numpy()
                                         != np.diff(idx)).any():
                raise ValueError(f'{name}.meta.parquet: rows do not match '
                                 'the offsets')
        return True

def fwedu_shards(which='100m', fetch=True, max_tokens=None):
    """The reference shards of FineWeb-Edu under the reference tokenizer:
    which='val' (2^23 validation tokens), '100m' (train-00000, 10^8 tokens)
    or '4b' (the 40 training shards, downloaded one by one when first read).
    Each lives in ../data/lm/fwedu-r2-v1/<which>/, extracted on the first
    call (make that call once before starting several processes).

    Defined in :numref:`sec_lm_tokenizers`"""
    keys = {'val': 'lm-fwedu-val-v1', '100m': 'lm-fwedu-shards-100m-v1',
            '4b': 'lm-fwedu-manifest-4b-v1'}
    if which not in keys:
        raise ValueError(f'which is one of {tuple(keys)}')
    key = keys[which]
    if key not in d2l.DATA_HUB:
        raise KeyError(f'{key} is not registered yet: it is built by '
                       'tools/build_r2_shards.py')
    root = os.path.join('..', 'data', 'lm', 'fwedu-r2-v1', which)
    path, sha1 = d2l.download_keyed(key), d2l.DATA_HUB[key][1]
    stamp = os.path.join(root, '.extracted-' + key)
    old = None
    if os.path.exists(stamp):
        with open(stamp) as f:
            old = f.read()
    if old != sha1:
        shutil.rmtree(root, ignore_errors=True)  # afresh when the
        os.makedirs(root)                        # registered sha1 changes
        if which == '4b':  # the manifest only; shards come when read
            shutil.copyfile(path, os.path.join(root, 'manifest.json'))
        else:
            d2l.extract(path, root)
        with open(stamp, 'w') as f:
            f.write(sha1)
    return d2l.TokenShards(root, 'val' if which == 'val' else 'train',
                           fetch=fetch, max_tokens=max_tokens)

def doc_ids_from_eos(tokens, eos_id=0):
    """Document index and position within the document of every token of a
    packed window (last axis); an EOS belongs to the document it ends.

    Defined in :numref:`sec_lm_data_path`"""
    is_eos = (tokens == eos_id).int()
    doc_ids = torch.cumsum(is_eos, -1) - is_eos   # EOS strictly before t
    t = torch.arange(tokens.shape[-1], device=tokens.device).expand_as(tokens)
    starts = torch.where(doc_ids != F.pad(doc_ids, (1, 0))[..., :-1], t, 0)
    first = torch.cummax(starts, -1).values       # where t's document starts
    return doc_ids.to(tokens.dtype), (t - first).to(tokens.dtype)

PackCtx = collections.namedtuple('PackCtx', ['doc_ids', 'pos_ids'])

def doc_mask_mod(doc_ids):
    """FlexAttention's mask predicate for packed windows.

    Defined in :numref:`sec_lm_data_path`"""
    return lambda b, h, q, k: (doc_ids[b, q] == doc_ids[b, k]) & (k <= q)

class PackedAttention(d2l.Qwen3Attention):
    """Qwen3Attention for packed windows: given ctx (a PackCtx), a query sees
    the earlier keys of its own document only. Backends: 'sdpa' (boolean
    mask), 'flex' (FlexAttention block mask, CUDA), 'math' (explicit scores,
    needed for an attention-logit softcap); 'auto' picks flex on CUDA.

    Defined in :numref:`sec_lm_data_path`"""
    def __init__(self, num_hiddens, num_heads, num_kv_heads, *,
                 backend='auto', softcap=None, **kwargs):
        super().__init__(num_hiddens, num_heads, num_kv_heads, **kwargs)
        self.backend, self.softcap = backend, softcap

    def forward(self, X, keys=None, values=None, mask=None, tables=None,
                ctx=None):
        backend = d2l._attn_backend(self, X, ctx)
        if backend == 'causal':  # one document per row: Qwen3Attention
            return super().forward(X, keys, values, mask, tables)
        if mask is None:  # PackedGPT builds the mask once for all blocks
            mask = d2l._doc_mask(ctx, backend, X.shape[1], X.device)
        q, k, v = self.qkv(X, tables=tables)
        gqa = self.num_kv_heads < self.num_heads
        if backend == 'flex':
            Y = d2l._flex_attention()(q, k, v, block_mask=mask,
                                      enable_gqa=gqa)
        elif backend == 'sdpa':
            Y = F.scaled_dot_product_attention(q, k, v, attn_mask=mask,
                                               enable_gqa=gqa)
        else:
            Y = d2l._math_attention(q, k, v, mask, self.softcap)
        return self.W_o(Y.transpose(1, 2).flatten(2))

    def set_rope(self, inv_freq=None, mscale=1.0):
        """RoPE frequencies (None: base rope_theta) and YaRN's scale m.

        Defined in :numref:`sec_lm_data_path`"""
        self.rope_inv_freq = (None if inv_freq is None else
                              torch.as_tensor(inv_freq, dtype=torch.float32))
        self.rope_mscale = mscale

    def qkv(self, X, offset=0, tables=None):
        """Qwen3Attention.qkv; without tables, the RoPE angles of positions
        offset, offset + 1, ... use this block's (possibly scaled) RoPE.

        Defined in :numref:`sec_lm_data_path`"""
        if self.rope and tables is None:
            tables = _rope_tables(
                torch.arange(X.shape[1], device=X.device) + offset,
                self.head_dim, self.rope_theta, self.rope_inv_freq,
                self.rope_mscale)
        return d2l.Qwen3Attention.qkv(self, X, offset, tables)

class PackedGPT(d2l.Qwen3GPT):
    """Qwen3GPT for pretraining on packed windows: forward(X, ctx) with
    per-document positions and the document mask, and the final hidden
    states for a chunked loss (return_hidden=True).

    Defined in :numref:`sec_lm_data_path`"""
    def __init__(self, vocab_size, num_hiddens, num_heads, num_kv_heads,
                 num_blks, *, pos='rope', backend='auto', softcap=None,
                 qk_norm=False, rope_theta=1e4, max_len=4096, **kwargs):
        self.packed_options = dict(rope=pos == 'rope', backend=backend,
                                   softcap=softcap)
        super().__init__(vocab_size, num_hiddens, num_heads, num_kv_heads,
                         num_blks, qk_norm=qk_norm, rope_theta=rope_theta,
                         max_len=max_len, **kwargs)
        self.pos = pos
        if pos == 'learned':  # an absolute table, indexed by pos_ids
            self.pos_emb = nn.Embedding(max_len, num_hiddens)
            nn.init.normal_(self.pos_emb.weight, std=0.02)

    def CausalAttention(self, d, H, *, bias, rope, num_kv_heads):
        return PackedAttention(d, H, num_kv_heads, bias=bias,
                               **self.attn_options, **self.packed_options)

    def forward(self, X, ctx=None, return_hidden=False, logits_to_keep=None):
        pos = (ctx.pos_ids if ctx is not None
               else torch.arange(X.shape[1], device=X.device))
        H, tables = self.token_emb(X), None
        if self.pos == 'learned':
            H = H + self.pos_emb(pos.long())
        else:  # RoPE angles of each token's position within its document
            tables = d2l._packed_rope_tables(self, pos)
        mask = d2l._packed_mask(self, ctx, X)  # once for every block
        for blk in self.blks:
            H = blk(H, mask, tables=tables, ctx=ctx)
        if logits_to_keep is not None:
            H = H[:, -logits_to_keep:]
        H = self.norm(H)
        W = self.lm_head.weight if hasattr(self, 'lm_head') else \
            self.token_emb.weight
        return (H, W) if return_hidden else F.linear(H, W)

    def set_rope(self, inv_freq=None, mscale=1.0, scheme='none', scale=1.0):
        """Use RoPE frequencies inv_freq (None: base) and YaRN's scale m in
        every block; the model then accepts scale times its trained length.

        Defined in :numref:`sec_lm_data_path`"""
        self.trained_len = self.trained_len or self.max_len
        self.rope_inv_freq = (None if inv_freq is None else
                              torch.as_tensor(inv_freq, dtype=torch.float32))
        self.rope_mscale, self.rope_scheme, self.rope_scale = (mscale, scheme,
                                                               scale)
        self.max_len = round(scale * self.trained_len)
        for blk in self.blks:
            blk.attention.set_rope(inv_freq, mscale)

    @torch.inference_mode()
    def forward_cached(self, X, ks, vs, t, all_logits=False):
        """Qwen3GPT.forward_cached with this model's (possibly scaled) RoPE;
        all_logits=True returns the logits of every new position.

        Defined in :numref:`sec_lm_data_path`"""
        if self.pos != 'rope':
            raise NotImplementedError('forward_cached needs RoPE positions; '
                                      'this model has a learned table')
        tables = _packed_rope_tables(
            self, torch.arange(t, t + X.shape[1], device=X.device))
        H = self.token_emb(X)
        for i, blk in enumerate(self.blks):
            H = H + blk.attention.forward_step(blk.norm1(H), (ks[i], vs[i], t),
                                               tables)
            H = H + blk.ffn(blk.norm2(H))
        H = self.norm(H if all_logits else H[:, -1])
        W = self.lm_head.weight if hasattr(self, 'lm_head') else \
            self.token_emb.weight
        return F.linear(H, W), ks, vs

    def config(self):
        """Every constructor argument and the RoPE scaling, as JSON values.

        Defined in :numref:`sec_lm_data_path`"""
        return _packed_config(self)

    @classmethod
    def from_arch(cls, arch, **kw):
        """A model of the shape d2l.r2_config(...).arch gives.

        Defined in :numref:`sec_lm_data_path`"""
        kw = dict(dict(head_dim=arch.d_h, ffn_hidden=arch.f,
                       qk_norm=arch.qk_norm, rope_theta=arch.rope_base,
                       tie_embeddings=arch.tie, max_len=arch.T), **kw)
        return cls(arch.vocab, arch.d, arch.H, arch.H_kv, arch.L, **kw)

    @classmethod
    def adopt(cls, model, backend='auto'):
        """A PackedGPT holding the weights of a d2l.Qwen3GPT (no copy).

        Defined in :numref:`sec_lm_data_path`"""
        with torch.device('meta'):
            new = cls(**_qwen3_shape(model), backend=backend)
        _check_same_tensors(new.state_dict(), model.state_dict())
        new.load_state_dict(model.state_dict(), assign=True)
        return new

def token_weighted_loss(logits, labels, ignore_index=-100):
    """Summed next-token NLL over the valid targets (fp32) and their count.

    Defined in :numref:`sec_lm_data_path`"""
    logits = logits.flatten(0, -2)
    sum_nll = F.cross_entropy(logits.to(torch.promote_types(
        logits.dtype, torch.float32)), labels.flatten(),
        ignore_index=ignore_index, reduction='sum')
    return sum_nll, (labels != ignore_index).sum()

def lm_loss_terms(h, W, y, ignore_index=-100):
    """Summed NLL and summed logsumexp^2 over the valid targets y, from the
    fp32 logits of hidden states h under output weights W.

    Defined in :numref:`sec_lm_data_path`"""
    logits = F.linear(h, W)
    logits = logits.to(torch.promote_types(logits.dtype, torch.float32))
    lse, valid = torch.logsumexp(logits, -1), y != ignore_index
    nll = lse - logits.gather(-1, y.clamp(min=0)[:, None])[:, 0]
    return torch.stack([torch.where(valid, nll, 0.0).sum(),
                        torch.where(valid, lse ** 2, 0.0).sum()])

def chunked_lm_loss(hidden, weight, labels, chunk=8192, z_loss=0.0,
                    ignore_index=-100):
    """token_weighted_loss(F.linear(hidden, weight), labels), chunk
    positions at a time: each chunk's logits are recomputed in the backward
    pass instead of stored. z_loss adds z_loss * logsumexp^2 per valid
    target (the z-loss of a pretraining run).

    Defined in :numref:`sec_lm_data_path`"""
    H, y = hidden.flatten(0, -2), labels.flatten()
    nll, z = sum(torch.utils.checkpoint.checkpoint(
        lm_loss_terms, H[i:i + chunk], weight, y[i:i + chunk], ignore_index,
        use_reentrant=False) for i in range(0, len(y), chunk))
    return nll + z_loss * z, (y != ignore_index).sum()

class PackedStream:
    """Windows of seq_len + 1 tokens at offsets i * seq_len of a shard set.
    Step s takes slice s of a permutation seeded by (seed, epoch), with the
    steps in skip removed; rank r takes every world-th window of it.
    Targets after an EOS are -100.

    Defined in :numref:`sec_lm_data_path`"""
    def __init__(self, shards, seq_len, global_batch, seed=0, rank=0, world=1,
                 epoch=0, skip=()):
        self.shards, self.seq_len, self.global_batch = (shards, seq_len,
                                                        global_batch)
        self.seed, self.rank, self.world, self.epoch = seed, rank, world, epoch
        self.skipped = tuple(sorted(set(skip)))
        self.n_seq = (shards.n_tokens - 1) // seq_len
        self.steps_per_epoch = self.n_seq // global_batch
        self.layout_hash, self.step = d2l._layout_hash(shards), 0

    def batch(self, step):
        idx = d2l._window_indices(self, step)  # step's permutation slice
        W = torch.from_numpy(d2l._windows(self, idx[self.rank::self.world]))
        X, Y = W[:, :-1].contiguous(), W[:, 1:].clone()
        Y[X == self.shards.eos_id] = -100  # the next token starts a document
        doc_ids, pos_ids = doc_ids_from_eos(X.int(), self.shards.eos_id)
        return dict(input_ids=X, labels=Y, doc_ids=doc_ids, pos_ids=pos_ids)

    def __iter__(self):  # the cursor: step counts the batches consumed
        while True:
            self.step += 1
            yield self.batch(self.step - 1)

    def state_dict(self):
        return dict(version=1, seed=self.seed, epoch=self.epoch,
                    step=self.step, skip=list(self.skipped),
                    layout_hash=self.layout_hash, seq_len=self.seq_len,
                    global_batch=self.global_batch)

    def load_state_dict(self, state):
        for key in ('layout_hash', 'seq_len', 'global_batch'):
            if state[key] != getattr(self, key):
                raise ValueError(f'{key} {getattr(self, key)} != '
                                 f'{state[key]}')
        self.seed, self.epoch, self.step = (state['seed'], state['epoch'],
                                            state['step'])
        self.skipped = tuple(state['skip'])

    def physical_index(self, step):
        """The step of the unskipped schedule that logical step uses.

        Defined in :numref:`sec_lm_data_path`"""
        return _physical_step(self.skipped, step)

    def skip(self, step):
        """Drop physical step `step` (a bad batch); later steps move up.

        Defined in :numref:`sec_lm_data_path`"""
        self.skipped = tuple(sorted(set(self.skipped) | {step}))

Arch = collections.namedtuple('Arch',
                              'L d H H_kv d_h f vocab T rope_base qk_norm tie')

@dataclasses.dataclass
class PretrainConfig:
    """One pretraining run: the architecture, the batch (in sequences of
    arch.T tokens), the WSD schedule, AdamW, and what the run saves.

    Defined in :numref:`sec_lm_reference_model`"""
    preset: str
    arch: Arch
    steps: int
    global_batch: int
    micro_batch: int
    peak_lr: float
    warmup: int
    decay: int
    final_lr: float = 0.0
    betas: tuple = (0.9, 0.95)
    eps: float = 1e-8
    wd: float = 0.1
    clip: float = 1.0           # None: log the gradient norm, never clip
    clip_from: int = None       # clip after this many updates (None: all)
    z_loss: float = 1e-4
    dtype: str = 'bf16'
    compile: bool = True
    ddp: bool = False
    probe_every: int = 50       # update RMS per module
    stats_every: int = 50       # attention logit and entropy, log Z
    val_every: int = 250
    val_tokens: int = 2 ** 21
    ckpt_steps: tuple = ()      # bf16 weights after these steps
    state_steps: tuple = ()     # full training state after these steps
    state_every: int = 0        # and every state_every steps (last two kept)
    branches: tuple = ()        # (from_step, decay_steps) after the main run
    data: str = '100m'
    data_seed: int = 0
    seed: int = 0
    out_dir: str = None

    def accum(self, world):
        """Micro-batches per step on each of world GPUs."""
        if self.global_batch % (self.micro_batch * world):
            raise ValueError(f'{self.global_batch} sequences do not split '
                             f'into {world} x {self.micro_batch}')
        return self.global_batch // (self.micro_batch * world)

R2_ARCHS = {  # L, d, H, H_kv, f, qk_norm, T (head width 64, V = 32,768)
    'r2': (18, 768, 12, 4, 2048, False, 4096),
    'r2_short': (18, 768, 12, 4, 2048, False, 4096),
    't1': (8, 384, 6, 2, 1024, False, 1024),
    'fp8': (8, 768, 12, 4, 2048, True, 1024),
    'ladder-25m': (8, 384, 6, 2, 1024, False, 4096),
    'ladder-54m': (10, 576, 9, 3, 1536, False, 4096),
    'ladder-88m': (10, 768, 12, 4, 2048, False, 4096)}

R2_SCHEDULES = {  # sequences per step, steps, warmup, decay, peak LR, data
    'r2': (128, 6000, 300, 900, 6e-4, '4b'),
    'r2_short': (128, 2000, 100, 300, 6e-4, '4b'),
    't1': (64, 1526, 76, 229, 1e-3, '100m'),
    'fp8': (16, 1221, 60, 183, 1e-3, '100m'),
    'ladder-25m': (64, 1920, 48, 288, 1e-3, '4b'),
    'ladder-54m': (64, 4141, 104, 621, 8e-4, '4b'),
    'ladder-88m': (64, 6721, 168, 1008, 7e-4, '4b')}

def r2_config(preset='r2', **overrides):
    """The PretrainConfig of a preset; keyword arguments replace fields.

    Defined in :numref:`sec_lm_reference_model`"""
    L, d, H, H_kv, f, qk_norm, T = R2_ARCHS[preset]
    arch = Arch(L, d, H, H_kv, d // H, f, 32768, T, 1e4, qk_norm, True)
    B, steps, warmup, decay, lr, data = R2_SCHEDULES[preset]
    # the largest micro-batch that fits a 24 GB card (r2 at 8 does not)
    micro = 16 if T < 4096 else 4 if preset.startswith('r2') else 8
    cfg = PretrainConfig(preset, arch, steps, B, micro_batch=micro,
                         peak_lr=lr, warmup=warmup, decay=decay, data=data,
                         **d2l._preset_saves(preset))
    return dataclasses.replace(cfg, **overrides)

def flops_per_token(arch, T=None, causal_half=False):
    """Training FLOPs per token, 6 N_mm + 12 L H d_h T, of an Arch or a
    Transformers config (divide by 3 for a forward pass). N_mm counts the
    matrix parameters (the head once more when untied); T=None leaves out
    the attention scores; causal_half halves them.

    Defined in :numref:`sec_lm_reference_model`"""
    L, d, H, H_kv, d_h, f, V, tie = d2l._arch_fields(arch)
    N_mm = L * (2 * d * H * d_h + 2 * d * H_kv * d_h + 3 * d * f) + V * d
    N_mm += 0 if tie else V * d
    attn = 0 if T is None else 12 * L * H * d_h * T // (2 if causal_half
                                                        else 1)
    return 6 * N_mm + attn

def mfu(tokens_per_s, arch, peak_flops, n_gpus=1, *, T=None,
        causal_half=False):
    """Model FLOPs utilization: achieved training FLOP/s over the peak of
    n_gpus; T defaults to the arch's sequence length, if it has one.

    Defined in :numref:`sec_lm_reference_model`"""
    T = T if T is not None else getattr(arch, 'T', getattr(arch, 'seq_len',
                                                           None))
    F_tok = flops_per_token(arch, T=T, causal_half=causal_half)
    return tokens_per_s * F_tok / (peak_flops * n_gpus)

def wsd_lr(step, total, warmup, decay, peak, final=0.0):
    """Warmup-stable-decay: linear warmup, constant peak, linear decay to
    final over the last decay steps.

    Defined in :numref:`sec_lm_reference_model`"""
    if step < warmup:
        return peak * (step + 1) / warmup
    if step < total - decay:
        return peak
    return final + (peak - final) * (total - step) / decay

def param_groups(model, wd):
    """AdamW groups: weight decay on the matrices, none on embeddings,
    position tables and gains.

    Defined in :numref:`sec_lm_reference_model`"""
    decay, rest = [], []
    for name, p in model.named_parameters():
        no_decay = p.ndim < 2 or name.split('.')[0] in ('token_emb', 'pos_emb')
        (rest if no_decay else decay).append((name, p))
    return [dict(params=[p for _, p in g], names=[n for n, _ in g],
                 weight_decay=w) for g, w in ((decay, wd), (rest, 0.0))]

def pretrain_step(model, optimizer, micro_batches, cfg, n_valid, step=None):
    """One step on this rank's micro-batches; n_valid is the step's global
    count of valid targets, so the gradient is the token-weighted mean over
    every rank and micro-batch. step counts the updates before this one,
    as state_steps does, so clipping at cfg.clip starts at log step
    cfg.clip_from + 1. Returns loss, pre-clip norm, clipped and the mean
    log-partition log_z of the output softmax.

    Defined in :numref:`sec_lm_reference_model`"""
    world, nll, lse = d2l._rank_world()[1], 0.0, 0.0
    for k, mb in enumerate(micro_batches):
        ctx = d2l.PackCtx(mb['doc_ids'], mb['pos_ids'])
        with d2l._no_sync(model, k < len(micro_batches) - 1):  # sync last
            with torch.autocast(mb['input_ids'].device.type, torch.bfloat16,
                                enabled=cfg.dtype == 'bf16'):
                H, W = model(mb['input_ids'], ctx, return_hidden=True)
                loss, _, part, part_lse = d2l.chunked_lm_loss_and_nll(
                    H, W, mb['labels'], z_loss=cfg.z_loss, return_lse=True)
            (loss * world / n_valid).backward()  # DDP averages the ranks
        nll, lse = nll + part.detach(), lse + part_lse.detach()
    on = step is None or cfg.clip_from is None or step >= cfg.clip_from
    clip = (cfg.clip if on else None) or math.inf
    params = [p for g in optimizer.param_groups for p in g['params']]
    norm = torch.nn.utils.clip_grad_norm_(params, clip)
    optimizer.step()
    optimizer.zero_grad(set_to_none=True)
    loss, log_z = d2l._all_reduce_sum(torch.stack([nll, lse])) / n_valid
    return dict(loss=loss, grad_norm=norm, clipped=norm > clip, log_z=log_z)

def pretrain(model, stream, cfg, val_fn=None, hooks=(), resume=None):
    """Train model on stream under cfg, then each of cfg.branches from its
    saved state; one row per step (a DataFrame). resume: a state file, or
    'auto' for the latest one in cfg.out_dir.

    Defined in :numref:`sec_lm_reference_model`"""
    run = d2l._PretrainRun(model, stream, cfg, val_fn, resume)
    for seg in run.segments():  # the main run, then each branch
        for step in range(seg.start, seg.total):
            lr = wsd_lr(step, seg.total, cfg.warmup, seg.decay, cfg.peak_lr,
                        cfg.final_lr)
            for group in run.optimizer.param_groups:
                group['lr'] = lr
            t0 = time.perf_counter()
            batch, micro, n_valid = run.batch(step)  # this rank's part
            t1 = time.perf_counter()
            before = run.snapshot(step)  # weights before, at probe steps
            out = pretrain_step(run.model, run.optimizer, micro, cfg, n_valid,
                                step)
            row = dict(step=step + 1, tokens=(step + 1) * run.step_tokens,
                       lr=lr, **out)
            run.record(seg, row, batch, before, t1 - t0, t0)
            for hook in hooks:
                hook(step, run.raw, run.optimizer, batch, row)
            if run.stopped(row):  # a non-finite loss ends the segment
                break
    return run.finish()

def update_rms_by_phase(log, cfg, stable_from):
    """Medians per module kind of the logged update RMS (columns rms_<kind>,
    in units of the learning rate) over the stable phase (steps stable_from
    to the decay's start) and the decay; abs_<phase> multiplies them by the
    phase's median learning rate: the size of the update itself.

    Defined in :numref:`sec_lm_reference_model`"""
    run = log.set_index('step')
    rms = run.filter(like='rms_').dropna(how='all')
    decay_from = cfg.steps - cfg.decay
    out = {}
    for phase, rows in (('stable', rms.loc[stable_from:decay_from]),
                        ('decay', rms.loc[decay_from + 1:])):
        assert len(rows), f'the {phase} phase has no probe steps'
        out[phase] = rows.median()
        out[f'abs_{phase}'] = out[phase] * run.loc[rows.index, 'lr'].median()
    return pd.DataFrame(out).rename(lambda c: c.removeprefix('rms_'))

def moved(x, at, before=200, window=20, horizon=200, k=3, grid=10):
    """Steps after `at` until x moves (None within `horizon`): on blocks of
    `grid` steps (medians), the mean residual over `window` steps from the
    line fitted to the `before` steps before `at` leaves k standard errors
    of that line's prediction (residual scatter plus extrapolation).

    Defined in :numref:`sec_lm_reference_model`"""
    x = x.dropna()
    b = x.groupby((x.index - at) // grid).median()  # block j: at + grid * j
    ref, after = b.loc[-(before // grid):-1], b.loc[0:horizon // grid - 1]
    j, i = ref.index.to_numpy(float), after.index.to_numpy(float)
    line = np.polyfit(j, ref.to_numpy(), 1)
    s2 = ((ref - np.polyval(line, j)) ** 2).sum() / (len(j) - 2)
    w = max(1, window // grid)
    resid = (after - np.polyval(line, i)).rolling(w).mean()
    mid = pd.Series(i, after.index).rolling(w).mean() - j.mean()
    se = np.sqrt(s2 * (1 / w + 1 / len(j)
                       + mid ** 2 / ((j - j.mean()) ** 2).sum()))
    out = resid[resid.abs() > k * se]
    return int(grid * (out.index[0] + 1)) if len(out) else None

LogitStats = collections.namedtuple('LogitStats', ['max_logit', 'entropy'])

@torch.no_grad()
def attn_logit_stats(model, batch, max_seqs=1, chunk=512):
    """Largest attention logit (before a softcap) and mean attention entropy
    (of the softmax the block computes, after its softcap) of every head,
    per block, on the first max_seqs sequences of batch, from explicit
    scores (fused kernels return none); under DDP the maximum is over all
    ranks.

    Defined in :numref:`sec_lm_reference_model`"""
    X, ctx = d2l._probe_inputs(batch, max_seqs, model)
    stats = {}
    for l, (attn, Y, tables) in enumerate(d2l._attention_inputs(model, X,
                                                                ctx)):
        q, k, _ = attn.qkv(Y, tables=tables)
        k = k.repeat_interleave(attn.num_heads // attn.num_kv_heads, 1)
        m, ent = d2l._chunked_logit_stats(q, k, ctx, chunk,
                                          getattr(attn, 'softcap', None))
        stats[l] = LogitStats(d2l._all_reduce_max(m), ent)
    return stats

def softcap(x, c):
    """Smoothly cap x to (-c, c).

    Defined in :numref:`sec_lm_reference_model`"""
    return c * torch.tanh(x / c)

def make_bad_batch(batch, kind='random', vocab=32768, seed=0, k=None,
                   period=None, pool=None):
    """A batch shaped like batch of one-document windows, targets shifted
    ids: uniform random ids >= 32 ('random'), one repeated id ('repeat'),
    or ('ngram') k of batch's rows (all if k is None; the others untouched)
    replaced by one n-gram of period of the ids >= 32 of pool (default:
    batch's own), repeated.

    Defined in :numref:`sec_lm_reference_model`"""
    B, T = batch['input_ids'].shape
    g = torch.Generator().manual_seed(seed)
    pos = torch.arange(T, dtype=torch.int32).expand(B, T).contiguous()
    if kind == 'ngram':  # OLMo 2's spike shape
        pool = (batch['input_ids'] if pool is None else pool).flatten().cpu()
        pool = pool[pool >= 32]
        start = int(torch.randint(len(pool) - period + 1, (), generator=g))
        ids = pool[start:start + period].repeat(T // period + 1)[:T + 1]
        rows = torch.randperm(B, generator=g)[:k]
        bad = {key: v.clone() for key, v in batch.items()}
        for key, v in (('input_ids', ids[:-1]), ('labels', ids[1:]),
                       ('doc_ids', 0), ('pos_ids', pos[0])):
            bad[key][rows] = torch.as_tensor(v).to(bad[key])
        return bad
    if kind not in ('random', 'repeat'):
        raise ValueError(f'unknown bad-batch kind {kind!r}')
    ids = (torch.randint(32, vocab, (B, T + 1), generator=g) if kind ==
           'random' else torch.full((B, T + 1), 32 + seed % (vocab - 32)))
    return dict(input_ids=ids[:, :-1].contiguous(), labels=ids[:, 1:].clone(),
                doc_ids=torch.zeros_like(pos), pos_ids=pos)

def lr_sensitivity(final_losses, l0):
    """Wortsman et al.'s sensitivity: the mean over learning rates of
    min(loss, l0) - min(losses); a non-finite loss counts as l0.

    Defined in :numref:`sec_lm_reference_model`"""
    x = torch.tensor([float(v) for v in final_losses], dtype=torch.float64)
    x = torch.where(torch.isfinite(x), x, l0).clamp(max=l0)
    return float((x - x.min()).mean())

def qk_clip_(model, stats, tau, alpha=0.5):
    """Rescale in place the query and key rows of every head whose largest
    logit S exceeds tau: W_q by (tau/S)^alpha, W_k by (tau/S)^(1-alpha); a
    key head shared by a group of query heads uses the group's maximum.
    Heads at or below tau (a largest logit can be negative) keep factor 1.
    Returns each block's per-head logit factors; {} under QK-norm.

    Defined in :numref:`sec_lm_reference_model`"""
    import warnings
    raw = d2l._unwrap(model)
    if raw.blks[0].attention.qk_norm:
        warnings.warn('qk_clip_ does nothing under QK-norm')
        return {}
    factors = {}
    with torch.no_grad():
        for l, s in stats.items():
            attn = raw.blks[l].attention
            S = s.max_logit.to(attn.W_q.weight.device).float()
            S_kv = S.view(attn.num_kv_heads, -1).amax(1)  # per key head
            f_q = torch.where(S > tau, tau / S, 1.0) ** alpha
            f_k = torch.where(S_kv > tau, tau / S_kv, 1.0) ** (1 - alpha)
            d_h = attn.head_dim
            attn.W_q.weight.mul_(f_q.repeat_interleave(d_h)[:, None])
            attn.W_k.weight.mul_(f_k.repeat_interleave(d_h)[:, None])
            factors[l] = f_q * f_k.repeat_interleave(S.numel() //
                                                     S_kv.numel())
    return factors

def tau_rule(log, lo, hi):
    """QK-clip's threshold, fixed before the run that uses it: ten times the
    ceiling of a tenth of the largest logit in log over steps lo to hi.

    Defined in :numref:`sec_lm_reference_model`"""
    rows = log[log['step'].between(lo, hi)]
    return 10 * math.ceil(rows.filter(like='max_logit_').max().max() / 10)

def first_collapsed_rate(arms, variant, seed=None, floor=0.1):
    """The smallest learning rate at which an arm of variant (of seed, if
    given) had a layer whose mean attention entropy fell below floor nats
    at some statistics step; None if no rate collapsed.

    Defined in :numref:`sec_lm_reference_model`"""
    hit = arms[(arms['variant'] == variant) & (arms['min_entropy'] < floor)]
    if seed is not None:
        hit = hit[hit['seed'] == seed]
    return float(hit['lr'].min()) if len(hit) else None

def departure(x, start, before=200, window=20, k=3):
    """The first step from start + before on at which the rolling median of
    x over window steps leaves k MAD around the median of x over the before
    steps from start (for a paired series, so no trend line); None if it
    never does.

    Defined in :numref:`sec_lm_reference_model`"""
    x = x[x.index >= start].dropna()
    ref = x[x.index < start + before]
    center = ref.median()
    mad = (ref - center).abs().median()
    roll = x.rolling(window).median()
    out = roll[(roll.index >= start + before)
               & ((roll - center).abs() > k * mad)]
    return int(out.index[0]) if len(out) else None

def logit_fit(runs, at, level=0.95):
    """Per rate: the least-squares line of log largest logit on log N
    through runs (columns lr, seed, N, logit), its slope with a level
    interval (slope_hw, the half-width), and its prediction at N = at with
    a level prediction interval for the mean of log logit over as many
    seeds as runs has, back in logit units. A rate with a non-finite logit
    (a diverged run) gets no line: dropping the point would censor the
    largest logits.

    Defined in :numref:`sec_lm_reference_model`"""
    rows = []
    for lr, g in runs.groupby('lr'):
        x, y = np.log(g['N'].to_numpy(float)), np.log(g['logit'].to_numpy())
        n, x0 = len(x), math.log(at)
        if n < 3 or not np.isfinite(y).all():  # no interval from two points
            continue
        b, a = np.polyfit(x, y, 1)
        s = math.sqrt(((y - a - b * x) ** 2).sum() / (n - 2))  # residual sd
        sxx, t = ((x - x.mean()) ** 2).sum(), d2l.t_quantile(n - 2, level)
        h = t * s * math.sqrt(1 / g['seed'].nunique() + 1 / n
                              + (x0 - x.mean()) ** 2 / sxx)
        y0 = a + b * x0
        rows.append(dict(lr=lr, slope=b, slope_hw=t * s / math.sqrt(sxx),
                         intercept=a, predicted=math.exp(y0),
                         lo=math.exp(y0 - h), hi=math.exp(y0 + h)))
    return pd.DataFrame(rows, columns=['lr', 'slope', 'slope_hw', 'intercept',
                                       'predicted', 'lo', 'hi'])

def fp8_quant(x, fmt='e4m3', granularity='tensor', scale_mode='current',
              state=None):
    """Cast x to fp8: (q, scale) with q.float() * scale ≈ x. One scale per
    tensor, row, 1x128 tile or 128x128 block; current scaling takes the
    amax of x, delayed scaling the largest of the last 16 amaxes kept in
    state (a dict the call updates).

    Defined in :numref:`sec_lm_low_precision`"""
    dtype = {'e4m3': torch.float8_e4m3fn, 'e5m2': torch.float8_e5m2}[fmt]
    fmax = torch.finfo(dtype).max  # 448 (E4M3) or 57,344 (E5M2)
    tiles, untile = d2l._fp8_tiles(x.detach().float(), granularity)
    amax = tiles.abs().amax(-1, keepdim=True)  # one per tile
    if scale_mode == 'delayed':  # state: the caller's dict, kept per operand
        if state is None:
            raise ValueError('delayed scaling needs a state dict')
        history = state.get('amax', amax.expand(16, *amax.shape))
        state['amax'] = torch.cat([history[1:], amax[None]])
        amax = history.amax(0)  # from the earlier calls only
    scale = amax.clamp(min=1e-12) / fmax
    q = (tiles / scale).clamp(-fmax, fmax).to(dtype)  # saturate, round
    return untile(q), untile(scale)

E2M1 = (0.0, 0.5, 1.0, 1.5, 2.0, 3.0, 4.0, 6.0)  # the non-negative values

def fake_quant_fp4(x, block=16, scale='e4m3', rounding='rtn', dim=-1,
                   tensor_scale=True, generator=None):
    """x rounded to E2M1 times one scale per `block` values along dim.
    Scales: 'fp32'; 'e4m3' (NVFP4, under an fp32 tensor scale); 'pow2'
    (MXFP4's E8M0). Rounding: to nearest, ties to even ('rtn'), or
    stochastic ('sr').

    Defined in :numref:`sec_lm_low_precision`"""
    xt = x.float().movedim(dim, -1)
    xb = xt.reshape(-1, block)
    amax = xb.abs().amax(-1, keepdim=True)
    s = amax / 6  # the block's largest value lands on 6
    if scale == 'e4m3':  # block scales in E4M3, times one fp32 scale
        t = s.amax() / 448 if tensor_scale else s.new_ones(())
        t = torch.where(t > 0, t, 1.0)
        s = (s / t).to(torch.float8_e4m3fn).float() * t
    elif scale == 'pow2':  # 2^(floor(log2 amax) - 2): the top may clip
        s = torch.exp2(torch.floor(torch.log2(amax)) - 2)
    z = torch.where(s > 0, xb.abs() / s, 0.0).clamp(max=6)  # grid units
    grid = torch.tensor(E2M1, device=x.device)
    i = (torch.bucketize(z, grid, right=True) - 1).clamp(max=6)
    lo, hi = grid[i], grid[i + 1]  # the grid values around z
    frac = (z - lo) / (hi - lo)
    if rounding == 'sr':  # up with probability frac: unbiased
        up = frac > torch.rand(z.shape, generator=generator, device=z.device)
    else:  # to nearest; a tie goes to the even code (even index), as in E2M1
        up = (frac > 0.5) | ((frac == 0.5) & (i % 2 == 1))
    q = torch.where(up, hi, lo) * torch.sign(xb) * s
    return q.reshape(xt.shape).movedim(-1, dim).to(x.dtype)

def block_nmse(x, quantizer, block):
    """||Q(x) - x||^2 / ||x||^2 with Q = quantizer(blocks, block).

    Defined in :numref:`sec_lm_low_precision`"""
    xb = x.float().reshape(-1, block)
    return float(((quantizer(xb, block) - xb) ** 2).sum() / (xb ** 2).sum())

class _Fp8Matmul(torch.autograd.Function):
    """Y = X W^T and its two backward GEMMs on fp8 operands.

    Defined in :numref:`sec_lm_low_precision`"""
    @staticmethod
    def forward(ctx, X, W, lin, training):
        x = lin.quant(X, 'x', training)  # (q, scale), E4M3
        w = lin.quant(W, 'w', training)
        ctx.lin, ctx.dtypes = lin, (X.dtype, W.dtype)
        ctx.save_for_backward(*x, *w)
        return d2l._fp8_mm(x, w, lin.native, d2l._out_dtype(X), tb=True)

    @staticmethod
    def backward(ctx, dY):
        xq, xs, wq, ws = ctx.saved_tensors
        dy, native = ctx.lin.quant(dY, 'dy'), ctx.lin.native  # E5M2
        dX = d2l._fp8_mm(dy, (wq, ws), native, ctx.dtypes[0])  # dY W
        dW = d2l._fp8_mm(dy, (xq, xs), native, ctx.dtypes[1], ta=True)
        return dX, dW, None, None  # dW = dY^T X

class Fp8Linear(nn.Linear):
    """nn.Linear with fp8 GEMMs: X, W in E4M3, dY in E5M2, fp32
    accumulation; simulated, or native (torch._scaled_mm, Ada or newer).
    While self.track, .stats() reports each training step's casts.

    Defined in :numref:`sec_lm_low_precision`"""
    def __init__(self, in_features, out_features, bias=False,
                 granularity='tensor', scale_mode='current', native=False):
        super().__init__(in_features, out_features, bias=bias)
        self.granularity, self.scale_mode = granularity, scale_mode
        self.native, self.track, self.records = native, False, []
        self.state = {'x': {}, 'w': {}, 'dy': {}}  # delayed: amax histories

    def quant(self, t, role, training=True):
        """A cast of operand role; outside training (no gradients, e.g. a
        validation pass) the amax history is read but not updated."""
        fmt = 'e5m2' if role == 'dy' else 'e4m3'
        gran = d2l._fp8_granularity(self.granularity, role)
        state = self.state[role] if training else dict(self.state[role])
        q, s = fp8_quant(t, fmt, gran, self.scale_mode, state)
        if self.track and training:
            self.records.append(d2l._fp8_record(t, q, s, fmt, gran, role))
        return q, s

    def forward(self, X):
        Y = _Fp8Matmul.apply(X.reshape(-1, X.shape[-1]), self.weight, self,
                             torch.is_grad_enabled())
        Y = Y.reshape(*X.shape[:-1], -1)
        return Y if self.bias is None else Y + self.bias

    def stats(self):  # the mean per operand since the last call
        table, self.records = d2l._fp8_stats_table(self.records), []
        return table

class _Fp4Matmul(torch.autograd.Function):
    """Y = X W^T with simulated NVFP4 operands (the NVFP4 recipe).

    Defined in :numref:`sec_lm_low_precision`"""
    @staticmethod
    def forward(ctx, X, W, lin):
        ctx.lin = lin
        ctx.save_for_backward(X, W)
        Wq = d2l._fp4_weight(W, lin.block, lin.weight_block2d)
        return d2l._f32_mm(fake_quant_fp4(X, lin.block), Wq.T,
                           d2l._out_dtype(X))

    @staticmethod
    def backward(ctx, dY):
        (X, W), lin = ctx.saved_tensors, ctx.lin
        q = lambda t, r, dim=-1: fake_quant_fp4(t, lin.block, rounding=r,
                                                dim=dim)
        sr = 'sr' if lin.sr_grads else 'rtn'  # stochastic for gradients
        Wq = d2l._fp4_weight(W, lin.block, lin.weight_block2d, dim=0)
        dX = d2l._f32_mm(q(dY, sr), Wq, X.dtype)  # dY W
        if lin.H is not None:  # rotate each 16 tokens: dY^T X is unchanged
            X, dY = d2l._rotate_rows(X, lin.H), d2l._rotate_rows(dY, lin.H)
        dW = d2l._f32_mm(q(dY, sr, 0).T, q(X, 'rtn', 0), W.dtype)
        return dX, dW, None  # dW = dY^T X, blocks along the tokens

class Fp4Linear(nn.Linear):
    """nn.Linear with simulated NVFP4 training GEMMs; numerics only.

    Defined in :numref:`sec_lm_low_precision`"""
    def __init__(self, in_features, out_features, bias=False, block=16,
                 weight_block2d=True, hadamard=16, sr_grads=True):
        super().__init__(in_features, out_features, bias=bias)
        self.block, self.weight_block2d = block, weight_block2d
        self.sr_grads = sr_grads
        H = (d2l._hadamard(hadamard, torch.Generator().manual_seed(0))
             if hadamard else None)  # a random Hadamard transform
        self.register_buffer('H', H, persistent=False)

    def forward(self, X):
        Y = _Fp4Matmul.apply(X.reshape(-1, X.shape[-1]), self.weight, self)
        Y = Y.reshape(*X.shape[:-1], -1)
        return Y if self.bias is None else Y + self.bias

class MixStream:
    """Batches of global_batch windows from several streams: step s draws
    each stream's count from a multinomial seeded by (seed, s) and takes
    that stream's next windows; the cursors follow from the seed alone.

    Defined in :numref:`sec_lm_continued_pretraining`"""
    def __init__(self, streams, weights, global_batch, seed=0, rank=0,
                 world=1):
        self.streams, self.global_batch = streams, global_batch
        self.weights = np.asarray(weights, dtype=float) / np.sum(weights)
        self.seq_len = streams[0].seq_len
        self.eos_id = streams[0].shards.eos_id
        self.seed, self.rank, self.world, self.step = seed, rank, world, 0
        self._cum = np.zeros((1, len(streams)), dtype=np.int64)

    def counts(self, step):
        rng = np.random.default_rng([self.seed, step])
        return rng.multinomial(self.global_batch, self.weights)

    def cursors(self, step):
        """Windows each stream has given before step (prefix sums)."""
        while len(self._cum) <= step:  # extend the table, doubling it
            n = len(self._cum)
            c = np.stack([self.counts(s) for s in range(n - 1, 2 * n - 1)])
            self._cum = np.concatenate([self._cum,
                                        self._cum[-1] + c.cumsum(0)])
        return self._cum[step]

    def batch(self, step):
        W = np.concatenate([d2l._stream_windows(s, int(a), int(k)) for s, a, k
                            in zip(self.streams, self.cursors(step),
                                   self.counts(step))])
        W = W[np.random.default_rng([self.seed, step, 1]).permutation(len(W))]
        return d2l._window_batch(W[self.rank::self.world], self.eos_id)

    def __iter__(self):
        while True:  # the cursor: step counts the batches consumed
            self.step += 1
            yield self.batch(self.step - 1)

    def state_dict(self):
        return dict(version=1, kind='mix', seed=self.seed, step=self.step,
                    weights=[float(w) for w in self.weights],
                    global_batch=self.global_batch, seq_len=self.seq_len,
                    streams=[[s.layout_hash, s.seed, s.epoch]
                             for s in self.streams])

    def load_state_dict(self, state):
        mine = self.state_dict()
        for key in ('kind', 'weights', 'global_batch', 'seq_len', 'streams'):
            if state.get(key) != mine[key]:
                raise ValueError(f'{key}: {mine[key]} != {state.get(key)}')
        if state['seed'] != self.seed:  # the cursors follow from the seed
            self._cum = self._cum[:1]
        self.seed, self.step = state['seed'], state['step']

def mix_streams(streams, weights, global_batch, seed=0, rank=0,
                world=1):
    """A MixStream: global_batch windows per step from streams in the
    shares weights (rank's slice of each batch).

    Defined in :numref:`sec_lm_continued_pretraining`"""
    return MixStream(streams, weights, global_batch, seed, rank, world)

def forgetting_gain(base, docs, n_boot=2000, seed=0):
    """Per arm: domain gain (base minus arm loss on the domain set) and
    forgetting (arm minus base loss on the general set), in nats per token,
    with 95% intervals from resampling documents (the same resamples for
    the base and every arm); fg.attrs['draws'] keeps the replicates.

    Defined in :numref:`sec_lm_continued_pretraining`"""
    draws = {}
    for i, (s, key, sign) in enumerate((('domain', 'gain', 1),
                                        ('general', 'forget', -1))):
        ids = base.loc[base['set'] == s, 'doc_id'].to_numpy()
        if len(ids) == 0:  # a pending result
            continue
        idx = np.stack([*d2l.cluster_resample(ids, n_boot, seed + i),
                        np.arange(len(ids))])  # the point estimate last
        def loss(df):  # token-weighted: summed NLL over scored tokens
            d = df[df['set'] == s].set_index('doc_id').loc[ids]
            nll, n = d['sum_nll'].to_numpy(), d['n_tokens'].to_numpy()
            return nll[idx].sum(1) / n[idx].sum(1)
        for arm, df in docs.groupby('arm', sort=False):
            draws.setdefault(arm, {})[key] = sign * (loss(base) - loss(df))
    rows = [dict(arm=arm, **{f'{k}{q}': v for k, x in d.items() for q, v in
                             zip(('', '_lo', '_hi'), (x[-1], *np.percentile(
                                 x[:-1], [2.5, 97.5])))})
            for arm, d in draws.items()]
    fg = pd.DataFrame(rows, columns=['arm', 'gain', 'gain_lo', 'gain_hi',
                                     'forget', 'forget_lo', 'forget_hi'])
    fg.attrs['draws'] = draws
    return fg

def rewarm_bump(runs, within=40):
    """Per arm: the bump, the largest rise of the general loss over the
    arm's own loss at step 0 in the first `within` steps (nats per token);
    the step of that peak; and how much of it the end has healed (peak
    minus final loss). A peak on the window's last evaluation is no
    transient (the loss is still rising: forgetting) and has NaN bump.

    Defined in :numref:`sec_lm_continued_pretraining`"""
    rows = []
    logs = runs.logs.dropna(subset=['general_loss'])
    for arm, g in logs[logs['arm'] != 'base'].groupby('arm', sort=False):
        loss = g.set_index('step')['general_loss'].sort_index()
        early = loss.loc[:within]
        if 0 not in loss.index or len(early) < 2:
            continue
        peak = early.iloc[1:].idxmax()
        rise = early.index[-1] > peak  # falls again inside the window
        rows.append(dict(arm=arm, step=peak,
                         bump=loss[peak] - loss[0] if rise else math.nan,
                         healed=loss[peak] - loss.iloc[-1] if rise
                         else math.nan))
    return pd.DataFrame(rows, columns=['arm', 'bump', 'step', 'healed'])

def rope_inv_freq(d_head, base=10000.0, scheme='none', s=1.0, L=4096,
                  alpha=1.0, beta=32.0):
    """RoPE frequencies of the d_head / 2 pairs for a window s times the
    trained length L: 'none' (the base frequencies), 'pi' (all divided by
    s), 'ntk' (the base raised by s^(d / (d - 2))), or 'yarn' (pairs that
    turn more than beta times within L kept, less than alpha times divided
    by s, a linear ramp over the pair index between).

    Defined in :numref:`sec_lm_long_context`"""
    if scheme not in ('none', 'pi', 'ntk', 'yarn'):
        raise ValueError(f'unknown scheme {scheme!r}')
    if scheme == 'ntk':
        base = base * s ** (d_head / (d_head - 2))
    theta = 1.0 / base ** (torch.arange(0, d_head, 2, dtype=torch.float32,
                                        device='cpu') / d_head)
    if scheme == 'pi':
        return theta / s
    if scheme == 'yarn':  # the pair index m at which a pair turns r times
        m = lambda r: d_head * math.log(L / (2 * math.pi * r)) / (
            2 * math.log(base))
        ramp = ((torch.arange(d_head // 2) - m(beta))
                / (m(alpha) - m(beta))).clamp(0, 1)
        return theta * (ramp / s + 1 - ramp)
    return theta

def yarn_mscale(s):
    """YaRN's scale of queries and keys, 0.1 ln s + 1 (1 for s <= 1): the
    attention logits grow by its square, the softmax scale stays.

    Defined in :numref:`sec_lm_long_context`"""
    return 0.1 * math.log(s) + 1.0 if s > 1 else 1.0

def make_recall_task(tokenizer, length, depth, n_pairs=None, n_candidates=8,
                     n_items=200, seed=0):
    """Key-value recall items of at most length tokens for score_choices:
    lines 'The value of <key> is <value>.' with distinct two-word keys and
    five-digit values, the queried line at fraction depth of the prompt,
    then the query 'The value of <key> is'; the choices are n_candidates
    distinct values of the haystack, the gold value among them once.

    Defined in :numref:`sec_lm_long_context`"""
    g = d2l.recall_generator(seed, length, depth)
    out = dict(prompts=[], choices=[], gold=[], depth_actual=[])
    for _ in range(n_items):
        keys, values, lines, start = d2l.recall_haystack(
            tokenizer, length, g, n_pairs, min_lines=n_candidates)
        q = round(depth * (len(lines) - 1))  # the queried line
        others = values[:q] + values[q + 1:]
        picks = torch.randperm(len(others), generator=g)[:n_candidates - 1]
        choices = [f' {values[q]}'] + [f' {others[i]}' for i in picks]
        order = torch.randperm(n_candidates, generator=g).tolist()
        out['prompts'].append(d2l.RECALL_HEAD + ''.join(lines)
                              + f'The value of {keys[q]} is')
        out['choices'].append([choices[j] for j in order])
        out['gold'].append(order.index(0))
        out['depth_actual'].append(start[q] / start[-1])
    return out

def nll_by_position(model, windows, edges, ctx=None):
    """Mean next-token loss (nats) of windows (n, T + 1) in each position
    bucket [edges[k], edges[k + 1]), with a 95% interval from resampling
    whole windows: DataFrame(bucket, nll, lo, hi).

    Defined in :numref:`sec_lm_long_context`"""
    nll = d2l.window_nlls(model, windows, ctx).double()  # (n, T)
    rows = []
    for lo, hi in zip(edges[:-1], edges[1:]):
        part = nll[:, lo:hi]
        rows.append((d2l.bucket_name(lo, hi), *d2l.window_ci(
            part.sum(1), torch.full((len(part),), float(hi - lo)))))
    return pd.DataFrame(rows, columns=['bucket', 'nll', 'lo', 'hi'])

def long_context_gain(model, windows, short_len, long_len, min_gap,
                      rare_ids, edges):
    """Loss drop (nats) from seeing the whole window of long_len tokens
    instead of the last short_len / 2 to short_len tokens, on rare tokens
    whose previous occurrence lies at least min_gap back, per gap bucket
    (edges[k], edges[k + 1]]: DataFrame(bucket, gain, lo, hi, n).

    Defined in :numref:`sec_lm_long_context`"""
    windows = torch.as_tensor(windows)[:, :long_len + 1]
    gain = (d2l.sliding_nlls(model, windows, short_len)
            - d2l.window_nlls(model, windows))
    gap = d2l.repeat_gaps(windows, rare_ids)  # 0: no earlier occurrence
    pairs = list(zip(edges[:-1], edges[1:]))
    sums, counts = d2l.gain_sums(gain, gap, pairs, min_gap)
    rows = [(d2l.bucket_name(lo, hi), *d2l.window_ci(sums[:, k],
                                                     counts[:, k]),
             int(counts[:, k].sum())) for k, (lo, hi) in enumerate(pairs)]
    return pd.DataFrame(rows, columns=['bucket', 'gain', 'lo', 'hi', 'n'])

def chip_specs():
    """The accelerator table, one row per chip (indexed by name): memory
    (GB, TB/s), on-chip SRAM (MB), dense peaks (TFLOP/s) in 16, 8 and 4
    bits, power (W), scale-up and scale-out bandwidth (GB/s), each row with
    its source and retrieval date. NaN where the vendor states nothing.

    Defined in :numref:`sec_lm_accelerator_design`"""
    df = d2l._hw_static('hw-chip-specs').set_index('chip')
    d2l._check_specs(df)  # sources, dates, and the book's four rows
    return df

def derive_ratios(df):
    """Add the design ratios to a chip table: the ridge point (FLOP/byte,
    dense 16-bit), the sweep time C / beta (ms), the scale-out and
    scale-up bytes per FLOP, and on-chip SRAM as a fraction of memory.

    Defined in :numref:`sec_lm_accelerator_design`"""
    out = df.copy()
    out['ridge16'] = df.p16_tflops / df.mem_bw_tbs  # TFLOP/s over TB/s
    out['sweep_ms'] = df.mem_gb / df.mem_bw_tbs
    flops = df.p16_tflops * 1e12
    out['net_bytes_per_flop'] = df.scaleout_gbs * 1e9 / flops
    out['scaleup_bytes_per_flop'] = df.scaleup_gbs * 1e9 / flops
    out['hbm_fraction_sram'] = df.sram_mb / (1000 * df.mem_gb)
    return out

def sweep_floor(specs, cfg, L, mem_util=0.9):
    """The decode floor of a model that fills each chip: the largest batch
    b_max of sequences of L tokens whose weights W and KV cache fit
    mem_util of memory, the step time (W + b_max L k_KV) / beta that every
    step at that batch needs (ms), and the per-user token rate it allows.

    Defined in :numref:`sec_lm_accelerator_design`"""
    mem = d2l.config_memory(cfg, L, 1)
    W, kv = mem['weights'], mem['kv_cache']  # bytes; KV of one sequence
    C, beta = specs.mem_gb * 1e9, specs.mem_bw_tbs * 1e12
    b_max = np.floor((mem_util * C - W) / kv)
    b_max = b_max.where(b_max >= 1)  # NaN: the weights alone do not fit
    floor_ms = (W + b_max * kv) / beta * 1e3
    return pd.DataFrame({'sweep_ms': C / beta * 1e3, 'b_max': b_max,
                         'floor_ms': floor_ms, 'user_tps_max': 1e3 / floor_ms})

def sram_chips_needed(model_bytes, sram_bytes, eta=0.8):
    """Chips of sram_bytes each that hold model_bytes when a fraction eta
    of every chip is usable (the rest holds activations and buffers).

    Defined in :numref:`sec_lm_accelerator_design`"""
    return math.ceil(model_bytes / (eta * sram_bytes))

def hw_copy_bench(nbytes, kind='copy', repeats=20, graph=True):
    """Bandwidth (GB/s) of streaming nbytes of fp32 on the GPU: 'read'
    reads them `passes` times in one kernel (passes x nbytes moved), 'copy'
    copies them once (2 nbytes: read + write). Returns gbs, ms per call
    (median of repeats) and its MAD.

    Defined in :numref:`sec_lm_accelerator_design`"""
    x = torch.empty(nbytes // 4, device='cuda').uniform_()
    if kind == 'read':
        passes = max(1, 2**28 // nbytes)  # at least 256 MiB per kernel
        fn, moved = (lambda: d2l.read_passes(x, passes)), passes * nbytes
    else:
        y = torch.empty_like(x)
        fn, moved = (lambda: y.copy_(x)), 2 * nbytes
    ms, mad = d2l._hw_stats(d2l._hw_time(fn, repeats, graph))
    return dict(gbs=moved / ms / 1e6, ms=ms, mad=mad)

def hw_matmul_op(m, n, k, dtype, device='cuda'):
    """A zero-argument (m x k) @ (k x n) product in a format: 'fp32',
    'tf32' (both FP32 storage), 'bf16', 'fp16', or 'fp8' (E4M3 with
    per-tensor scales through torch._scaled_mm, bf16 output; only on a GPU
    with fp8 tensor cores).

    Defined in :numref:`sec_lm_accelerator_design`"""
    if dtype == 'fp8' and not d2l.has_fp8_cores(device):
        raise ValueError(f'fp8 needs fp8 tensor cores (sm_89 or newer); '
                         f'{d2l.device_name(device)} has none')
    A = torch.randn(m, k, device=device)
    B = torch.randn(n, k, device=device)  # B.T is (k, n), column-major
    if dtype == 'fp8':
        (A8, s_A), (B8, s_B) = (d2l.fp8_quant(X, granularity='tensor')
                                for X in (A, B))
        return lambda: torch._scaled_mm(A8, B8.T, scale_a=s_A, scale_b=s_B,
                                        out_dtype=torch.bfloat16)
    store = {'fp32': torch.float32, 'tf32': torch.float32,
             'bf16': torch.bfloat16, 'fp16': torch.float16}[dtype]
    A, Bt = A.to(store), B.to(store).T
    return lambda: A @ Bt

def hw_matmul_bench(m, n, k, dtype, repeats=20, graph=True):
    """TFLOP/s of hw_matmul_op (2 m n k FLOPs per product): tflops, ms per
    product (median of repeats) and its MAD.

    Defined in :numref:`sec_lm_accelerator_design`"""
    fn = hw_matmul_op(m, n, k, dtype)
    with d2l._hw_tf32(dtype == 'tf32'):
        ms, mad = d2l._hw_stats(d2l._hw_time(fn, repeats, graph))
    return dict(tflops=2 * m * n * k / ms / 1e9, ms=ms, mad=mad)

def chunked_causal_attention(q, k, v, chunk=512):
    """Exact causal attention of q (B, H, N, d) against k and v
    (B, H_kv, N, d), one chunk of keys at a time with the online softmax;
    the H // H_kv query heads sharing a key-value head are stacked as rows
    against it (GQA without copying k and v).

    Defined in :numref:`sec_lm_kernels`"""
    B, H, N, d = q.shape
    H_kv = k.shape[1]
    Q = q.reshape(B, H_kv, H // H_kv * N, d)  # a group's queries as rows
    pos_q = torch.arange(N, device=q.device).repeat(H // H_kv)[:, None]
    lowest = torch.finfo(torch.float32).min
    m = torch.full((B, H_kv, Q.shape[2], 1), lowest, device=q.device)
    s = torch.zeros_like(m)
    O = torch.zeros(Q.shape, device=q.device)
    for start in range(0, N, chunk):
        Kc, Vc = k[:, :, start:start + chunk], v[:, :, start:start + chunk]
        pos_k = torch.arange(start, start + Kc.shape[2], device=q.device)
        a = (Q @ Kc.transpose(-2, -1)).float() / math.sqrt(d)
        a.masked_fill_(pos_k > pos_q, lowest)
        m_new = torch.maximum(m, a.amax(-1, keepdim=True))
        scale = torch.exp(m - m_new)  # rescale the past
        P = torch.exp(a - m_new)
        s = s * scale + P.sum(-1, keepdim=True)
        O = O * scale + (P.to(Vc.dtype) @ Vc).float()
        m = m_new
    return (O / s).to(q.dtype).view(B, H, N, d)

def tile_intensity(Tm, Tn, b=2):
    """FLOPs per byte loaded of a Tm x Tn output tile: each K-slab of depth
    T_k brings b T_k (Tm + Tn) bytes for 2 Tm Tn T_k FLOPs.

    Defined in :numref:`sec_lm_kernels`"""
    return 2 * Tm * Tn / (b * (Tm + Tn))

def tile_roof(rows, b=2, rf_kib=256):
    """For each chip (a chip_specs row): the ridge R = P / beta (FLOP per
    byte, dense 16-bit), the smallest square tile T = ceil(b R) that
    reaches it from DRAM, its FP32 accumulators 4 T^2 (KiB), and the
    register file of one SM (KiB).

    Defined in :numref:`sec_lm_kernels`"""
    R = rows.p16_tflops / rows.mem_bw_tbs  # TFLOP/s over TB/s
    T = np.ceil(b * R).astype(int)
    return pd.DataFrame({'ridge': R, 'T': T, 'acc_kib': 4 * T**2 / 2**10,
                         'rf_kib': rf_kib})

def gemm_shapes(cfg, tokens):
    """The weight products of one forward pass over `tokens` tokens of a
    decoder (an Arch or a Transformers config): per product, the shape
    M x N x K of one layer's matmul and the GFLOP over all layers (the head
    once). The attention scores are not weight products.

    Defined in :numref:`sec_lm_kernels`"""
    L, d, H, H_kv, d_h, f, V, _ = d2l.arch_dims(cfg)  # _: tied or not
    products = [('QKV', (H + 2 * H_kv) * d_h, d, L), ('out', d, H * d_h, L),
                ('gate-up', 2 * f, d, L), ('down', d, f, L), ('head', V, d, 1)]
    return pd.DataFrame([
        dict(name=name, M=tokens, N=n, K=k, gflop=2 * tokens * n * k * c / 1e9)
        for name, n, k, c in products])

@triton.jit
def _rmsnorm_kernel(X, W, Y, d, eps, BLOCK: tl.constexpr):
    row = tl.program_id(0)  # one program per row
    cols = tl.arange(0, BLOCK)
    mask = cols < d
    x = tl.load(X + row * d + cols, mask=mask, other=0.0).to(tl.float32)
    w = tl.load(W + cols, mask=mask, other=0.0).to(tl.float32)
    r = tl.rsqrt(tl.sum(x * x, axis=0) / d + eps)
    tl.store(Y + row * d + cols, (x * r * w).to(Y.dtype.element_ty),
             mask=mask)

def triton_rmsnorm(x, weight, eps=1e-6):
    """RMSNorm over the last dimension of x in one Triton kernel (one
    program per row, FP32 accumulation).

    Defined in :numref:`sec_lm_kernels`"""
    X = x.reshape(-1, x.shape[-1]).contiguous()
    Y = torch.empty_like(X)
    _rmsnorm_kernel[(X.shape[0],)](X, weight, Y, X.shape[1], eps,
                                   BLOCK=triton.next_power_of_2(X.shape[1]))
    return Y.view_as(x)

def rms_norm_formula(x, weight, eps=1e-6):
    """RMSNorm as written: x / sqrt(mean(x^2) + eps) * weight.

    Defined in :numref:`sec_lm_kernels`"""
    return x * torch.rsqrt(x.pow(2).mean(-1, keepdim=True) + eps) * weight

@triton.jit
def _attend(q, K_tile, V_tile, m, s, acc, start, rows, N, scale,
            MASK: tl.constexpr, CAUSAL: tl.constexpr, BLOCK_K: tl.constexpr):
    """One key-value tile of the online softmax of a query tile.

    Defined in :numref:`sec_lm_kernels`"""
    k = tl.load(K_tile, boundary_check=(0,))
    a = tl.dot(q, tl.trans(k)) * scale  # scores in log2 units
    if MASK:  # a tile on the diagonal, or past the last key
        cols = start + tl.arange(0, BLOCK_K)
        keep = cols[None, :] < N
        if CAUSAL:
            keep = keep & (rows[:, None] >= cols[None, :])
        a = tl.where(keep, a, float('-inf'))
    m_new = tl.maximum(m, tl.max(a, axis=1))
    alpha = tl.exp2(m - m_new)  # rescale the past
    p = tl.exp2(a - m_new[:, None])
    v = tl.load(V_tile, boundary_check=(0,))
    acc = acc * alpha[:, None] + tl.dot(p.to(v.dtype), v)
    return m_new, s * alpha + tl.sum(p, axis=1), acc

@triton.jit
def _flash_fwd_kernel(Q, K, V, O, sm_scale, N, H, GROUP: tl.constexpr,
                      D: tl.constexpr, BLOCK_Q: tl.constexpr,
                      BLOCK_K: tl.constexpr, CAUSAL: tl.constexpr):
    i, bh = tl.program_id(0), tl.program_id(1)  # query tile, (batch, head)
    b, h = bh // H, bh % H
    q_base = bh * N * D
    kv_base = (b * (H // GROUP) + h // GROUP) * N * D  # the shared KV head
    Q_tile = tl.make_block_ptr(Q + q_base, (N, D), (D, 1), (i * BLOCK_Q, 0),
                               (BLOCK_Q, D), (1, 0))
    K_tile = tl.make_block_ptr(K + kv_base, (N, D), (D, 1), (0, 0),
                               (BLOCK_K, D), (1, 0))
    V_tile = tl.make_block_ptr(V + kv_base, (N, D), (D, 1), (0, 0),
                               (BLOCK_K, D), (1, 0))
    q = tl.load(Q_tile, boundary_check=(0,))
    m = tl.full([BLOCK_Q], float('-inf'), tl.float32)
    s = tl.zeros([BLOCK_Q], tl.float32)
    acc = tl.zeros([BLOCK_Q, D], tl.float32)
    scale = sm_scale * 1.4426950408889634  # e^x = 2^(x log2 e)
    rows = i * BLOCK_Q + tl.arange(0, BLOCK_Q)
    if CAUSAL:  # full tiles below the diagonal, then the diagonal tiles
        lo = i * BLOCK_Q // BLOCK_K * BLOCK_K
        hi = tl.minimum((i + 1) * BLOCK_Q, N)  # later keys: skipped
    else:
        lo, hi = N // BLOCK_K * BLOCK_K, N
    for start in range(0, lo, BLOCK_K):
        m, s, acc = _attend(q, K_tile, V_tile, m, s, acc, start, rows, N,
                            scale, False, CAUSAL, BLOCK_K)
        K_tile = tl.advance(K_tile, (BLOCK_K, 0))
        V_tile = tl.advance(V_tile, (BLOCK_K, 0))
    for start in range(lo, hi, BLOCK_K):
        m, s, acc = _attend(q, K_tile, V_tile, m, s, acc, start, rows, N,
                            scale, True, CAUSAL, BLOCK_K)
        K_tile = tl.advance(K_tile, (BLOCK_K, 0))
        V_tile = tl.advance(V_tile, (BLOCK_K, 0))
    O_tile = tl.make_block_ptr(O + q_base, (N, D), (D, 1), (i * BLOCK_Q, 0),
                               (BLOCK_Q, D), (1, 0))
    tl.store(O_tile, (acc / s[:, None]).to(O.dtype.element_ty),
             boundary_check=(0,))

def flash_attention_triton(q, k, v, causal=True, block_q=128,
                           block_k=64, num_warps=4, num_stages=2):
    """Attention forward of q (B, H, N, d) against k and v (B, H_kv, N, d)
    in one Triton kernel: one program per query tile and head, the online
    softmax over key-value tiles; no dropout, no backward. Offsets are
    32-bit: each tensor holds fewer than 2^31 elements.

    Defined in :numref:`sec_lm_kernels`"""
    q, k, v = q.contiguous(), k.contiguous(), v.contiguous()
    B, H, N, D = q.shape
    o = torch.empty_like(q)
    grid = (triton.cdiv(N, block_q), B * H)
    _flash_fwd_kernel[grid](q, k, v, o, 1 / math.sqrt(D), N, H,
                            GROUP=H // k.shape[1], D=D, BLOCK_Q=block_q,
                            BLOCK_K=block_k, CAUSAL=causal,
                            num_warps=num_warps, num_stages=num_stages)
    return o

class ServingModel:
    """Time and memory of serving a dense Qwen3 or Qwen3-MoE configuration
    on n_chips identical chips (a chip_specs row): weights of dtype_bytes,
    KV entries of kv_bytes (or kv_bytes_override bytes per token), the
    fraction mem_util of memory usable. A calibration (hw_calibrate)
    replaces the datasheet's FLOP/s and bandwidth by measured ones.

    Defined in :numref:`sec_lm_workload_hardware`"""
    def __init__(self, cfg, chip, calib=None, dtype_bytes=2, kv_bytes=2,
                 mem_util=0.9, kv_bytes_override=None, n_chips=1):
        self.cfg, self.calib = d2l._hw_cfg(cfg), dict(calib or {})
        self.n_chips = n_chips
        self.dtype_bytes, self.kv_bytes = dtype_bytes, kv_bytes
        self.kv_override = kv_bytes_override
        P, beta = d2l.hw_rates(chip, calib, dtype_bytes)  # FLOP/s, byte/s
        self.P, self.beta = n_chips * P, n_chips * beta
        self.C = n_chips * chip.mem_gb * 1e9 * mem_util  # usable bytes

    def experts(self):
        """(E, K, d_ff of an expert, MoE layers); (1, 1, d_ff, 0) when dense.

        Defined in :numref:`sec_lm_workload_hardware`"""
        c = self.cfg
        E = getattr(c, 'num_experts', 0) or 0
        if E <= 1:
            return 1, 1, c.intermediate_size, 0
        dense = set(getattr(c, 'mlp_only_layers', None) or [])
        n_moe = sum(1 for i in range(c.num_hidden_layers)
                    if i not in dense and (i + 1) % c.decoder_sparse_step == 0)
        return E, c.num_experts_per_tok, c.moe_intermediate_size, n_moe

    def n_params(self):
        """(total, active): every expert, or the K experts a token uses.

        Defined in :numref:`sec_lm_workload_hardware`"""
        c, (E, K, f, n_moe) = self.cfg, self.experts()
        d, n_layers, d_h = c.hidden_size, c.num_hidden_layers, c.head_dim
        attn = 2 * d * d_h * (c.num_attention_heads + c.num_key_value_heads)
        norms = 2 * d_h + 2 * d  # query and key norms, two layer norms
        embed = c.vocab_size * d * (1 if c.tie_word_embeddings else 2) + d
        base = (embed + n_layers * (attn + norms)
                + (n_layers - n_moe) * 3 * d * c.intermediate_size)
        return (base + n_moe * (E * 3 * d * f + d * E),
                base + n_moe * (K * 3 * d * f + d * E))

    def weight_bytes(self):
        return self.n_params()[0] * self.dtype_bytes

    def kv_bytes_per_token(self):
        if self.kv_override is not None:
            return self.kv_override
        c = self.cfg
        return (2 * c.num_hidden_layers * c.num_key_value_heads * c.head_dim
                * self.kv_bytes)

    def n_matmul(self):
        """N_act: active parameters less a separate input embedding table.

        Defined in :numref:`sec_lm_workload_hardware`"""
        c = self.cfg
        lookup = 0 if c.tie_word_embeddings else c.vocab_size * c.hidden_size
        return self.n_params()[1] - lookup

    def n_body(self):
        """N_act less the LM head: the matrix parameters of the layers.

        Defined in :numref:`sec_lm_workload_hardware`"""
        return self.n_matmul() - self.cfg.vocab_size * self.cfg.hidden_size

    def read_bytes(self, b, coverage=None):
        """Weight bytes one step of b tokens reads; coverage: the fraction of
        experts they touch (a number, a function of b, or None for uniform
        routing).

        Defined in :numref:`sec_lm_workload_hardware`"""
        c, (E, K, f, n_moe) = self.cfg, self.experts()
        lookup = 0 if c.tie_word_embeddings else c.vocab_size * c.hidden_size
        W = self.weight_bytes() - lookup * self.dtype_bytes
        if n_moe == 0:
            return W
        frac = coverage(b) if callable(coverage) else coverage
        if frac is None:
            frac = d2l.moe_expert_coverage(E, K, b) / E
        expert_bytes = 3 * c.hidden_size * f * self.dtype_bytes
        return W - n_moe * E * expert_bytes * (1 - frac)

    def prefill_time(self, n, b=1):
        """Seconds to prefill b prompts of n tokens up to the last position's
        logits: the larger of the FLOP time and the time to read the weights
        and write the cache.

        Defined in :numref:`sec_lm_workload_hardware`"""
        c = self.cfg
        head = self.n_matmul() - self.n_body()  # V d, run on the last position
        attn = 2 * c.num_hidden_layers * c.num_attention_heads * c.head_dim * n**2
        flops = b * (2 * self.n_body() * n + 2 * head + attn)
        nbytes = self.read_bytes(b * n) + b * n * self.kv_bytes_per_token()
        return max(flops / self.P, nbytes / self.beta) + self.launch()

    def prefill_crossover(self):
        """Prompt length at which attention FLOPs equal the FLOPs of the
        layers' matrix products.

        Defined in :numref:`sec_lm_workload_hardware`"""
        c = self.cfg
        return self.n_body() / (c.num_hidden_layers * c.num_attention_heads
                                * c.head_dim)

    def decode_terms(self, b, L, coverage=None):
        """Seconds of one decode step of b sequences at context L: matrix
        products, memory reads (weights, then every sequence's cache), and the
        launch term of a calibrated chip.

        Defined in :numref:`sec_lm_workload_hardware`"""
        t_compute = 2 * self.n_matmul() * b / self.P
        eta_kv = self.calib.get('eta_kv', 1.0)  # fitted cache-read efficiency
        t_memory = (self.read_bytes(b, coverage) / self.beta
                    + b * L * self.kv_bytes_per_token() / (eta_kv * self.beta))
        return t_compute, t_memory, self.launch()

    def decode_step(self, b, L, coverage=None):
        t_compute, t_memory, t_launch = self.decode_terms(b, L, coverage)
        return float(np.maximum(t_compute, t_memory)) + t_launch  # NaN stays

    def max_batch(self, L):
        """Largest b whose weights and caches fit (derivation D2).

        Defined in :numref:`sec_lm_workload_hardware`"""
        free = self.C - self.weight_bytes()
        return max(0, int(free // (L * self.kv_bytes_per_token())))

    def L_crit(self):
        """Context beyond which no batch makes decode compute-bound.

        Defined in :numref:`sec_lm_workload_hardware`"""
        k = self.kv_bytes_per_token() / self.calib.get('eta_kv', 1.0)
        return 2 * self.n_matmul() / (self.P / self.beta * k)

    def b_star(self, L):
        """Batch at which decode turns compute-bound (inf beyond L_crit).

        Defined in :numref:`sec_lm_workload_hardware`"""
        k = self.kv_bytes_per_token() / self.calib.get('eta_kv', 1.0)
        slack = 2 * self.n_matmul() / (self.P / self.beta) - L * k
        return self.read_bytes(1) / slack if slack > 0 else math.inf

    def launch(self, passes=1):
        """Kernel cost of passes forward passes on a calibrated chip (M2):
        kernels per forward times alpha_k (times a fitted kappa in M3).

        Defined in :numref:`sec_lm_workload_hardware`"""
        k = self.calib
        return (passes * k.get('kernels_per_step', 0) * k.get('alpha_k', 0.0)
                * k.get('kappa', 1.0))

    def frontier(self, L, batches):
        """Per-user and per-GPU tokens/s at each context in L and batch in
        batches and at the capacity limit max_batch(L); regime 'bw', 'compute'
        or 'infeasible' (beyond max_batch).

        Defined in :numref:`sec_lm_workload_hardware`"""
        rows = []
        for L_i in np.atleast_1d(L):
            b_max = self.max_batch(int(L_i))
            for b in sorted(set(np.atleast_1d(batches)) | {max(b_max, 1)}):
                t_c, t_m, t_l = self.decode_terms(int(b), int(L_i))
                t = max(t_c, t_m) + t_l
                regime = ('infeasible' if b > self.max_batch(L_i) else
                          'compute' if t_c > t_m else 'bw')
                rows.append(dict(b=int(b), L=int(L_i), user_tps=1 / t,
                                 gpu_tps=b / t / self.n_chips, regime=regime))
        return pd.DataFrame(rows)

    def gpu_s_per_mtok(self, b, L):
        """GPU-seconds per million generated tokens at batch b, context L.

        Defined in :numref:`sec_lm_workload_hardware`"""
        return 1e6 * self.decode_step(b, L) * self.n_chips / b

class TrainStepModel:
    """Seconds per training step on one chip: forward and backward at its
    FLOP/s, then one AdamW pass over the state at its bandwidth. Recipe
    'bf16_pure' keeps weights, gradients and both moments in bf16;
    'mixed16' adds fp32 master weights and fp32 moments.

    Defined in :numref:`sec_lm_workload_hardware`"""
    state = {'bf16_pure': 8, 'mixed16': 16}  # bytes held per parameter
    traffic = {'bf16_pure': 14, 'mixed16': 28}  # bytes AdamW moves per one
    loss_bytes = 40  # per logit: about ten fp32 passes over the logits

    def __init__(self, cfg, chip, calib=None, recipe='bf16_pure'):
        self.cfg, self.chip, self.recipe = d2l._hw_cfg(cfg), chip, recipe
        self.serving = d2l.ServingModel(cfg, chip, calib)  # counts, rates
        self.N = self.serving.n_params()[0]

    def flops_per_token(self, s):
        """Chapter 21's count, less an untied input embedding (a lookup)
        plus the head's forward again (chunked_lm_loss recomputes it)."""
        c = self.cfg
        head = c.vocab_size * c.hidden_size
        lookup = 0 if c.tie_word_embeddings else head
        return (d2l.flops_per_token(c, T=s, causal_half=True)
                - 6 * lookup + 2 * head)

    def step_time(self, b, s, ckpt=False):
        """b sequences of s tokens; ckpt recomputes the forward pass.

        Defined in :numref:`sec_lm_workload_hardware`"""
        m = self.serving
        flops = self.flops_per_token(s) * b * s * (4 / 3 if ckpt else 1)
        logits = self.cfg.vocab_size * b * s  # each one moved in fp32 by the loss
        return (flops / m.P + (self.traffic[self.recipe] * self.N
                               + self.loss_bytes * logits) / m.beta
                + m.launch(passes=3))  # forward, and backward twice its kernels

    def mfu(self, tokens_per_s, s):
        """Model FLOPs utilization against the datasheet's bf16 peak.

        Defined in :numref:`sec_lm_workload_hardware`"""
        return d2l.mfu(tokens_per_s, self.cfg, self.chip.p16_tflops * 1e12,
                       T=s, causal_half=True)

def moe_expert_coverage(E, K, b):
    """Expected number of distinct experts that b tokens touch when each
    picks K of E uniformly (and independently of the others).

    Defined in :numref:`sec_lm_workload_hardware`"""
    return E * (1 - (1 - K / E)**b)

def hw_calibrate(device=None, log=None):
    """The chip as measured: P_eff_bf16 (FLOP/s), beta_eff (byte/s),
    alpha_k (seconds per kernel in a CUDA graph), the GPU, and the
    all-reduce's alpha_ar and beta_ar (None until 22.5's fit is committed).
    From log, the box-microbench tables, or measured now on device (about
    half a minute); None without a GPU or a committed log.

    Defined in :numref:`sec_lm_workload_hardware`"""
    tables = d2l._calib_tables(log, device)  # copies by size, bf16 products
    if tables is None:
        return None
    copy, bf16_tflops, gpu = tables
    alpha_k, _, _ = d2l.fit_alpha_beta(2 * copy.bytes, copy.ms / 1e3)
    return dict(P_eff_bf16=bf16_tflops.max() * 1e12,  # the best product
                beta_eff=copy.gbs.iloc[-1] * 1e9,  # the largest copy
                alpha_k=alpha_k,  # the intercept: one kernel's fixed cost
                gpu=gpu, **d2l._calib_allreduce())  # None before 22.5

def hw_decode_bench(model, b, L, steps=64):
    """Milliseconds per decode step of b sequences at context L: median
    and MAD over steps replays of one CUDA graph.

    Defined in :numref:`sec_lm_workload_hardware`"""
    token = torch.randint(model.config.vocab_size, (b, 1), device='cuda')
    with torch.inference_mode():
        cache, refill = d2l.hw_static_cache(model, b, L)
        position = torch.tensor([L], device='cuda')

        def step():  # the cache holds L tokens again: every replay is alike
            refill()
            model(token, past_key_values=cache, cache_position=position,
                  logits_to_keep=1)
        times = d2l._hw_time(step, steps, max_inner=1)  # events, graph
    ms, mad = d2l._hw_stats(times)  # median and MAD
    return dict(ms=ms, mad=mad)

def hw_prefill_bench(model, n, b=1, repeats=5):
    """Milliseconds to prefill b random prompts of n tokens: median and MAD
    after one warm-up.

    Defined in :numref:`sec_lm_workload_hardware`"""
    ids = torch.randint(model.config.vocab_size, (b, n), device='cuda')
    start, stop = (torch.cuda.Event(enable_timing=True) for _ in range(2))
    times = []
    for _ in range(1 + repeats):
        start.record()
        out = d2l.hf_prefill(model, ids, n, keep=1)[0]
        stop.record()
        stop.synchronize()
        times.append(start.elapsed_time(stop))
        del out
    ms, mad = d2l._hw_stats(times[1:])  # median and MAD
    return dict(ms=ms, mad=mad)

def hw_train_bench(model, b, s, repeats=10, warmup=3, chunk=2048):
    """Milliseconds per training step on b random sequences of s tokens:
    median and MAD.

    Defined in :numref:`sec_lm_workload_hardware`"""
    model.train()
    opt = torch.optim.AdamW(model.parameters(), lr=1e-4, fused=True)
    ids = torch.randint(model.config.vocab_size, (b, s + 1), device='cuda')

    def step():
        hidden = model.model(input_ids=ids[:, :-1]).last_hidden_state
        loss, n = d2l.chunked_lm_loss(hidden, model.lm_head.weight,
                                      ids[:, 1:], chunk=chunk)
        (loss / n).backward()
        opt.step()
        opt.zero_grad(set_to_none=True)
    times = d2l._hw_time(step, repeats, graph=False, max_inner=1,
                         warmup=warmup)  # CUDA events around eager steps
    ms, mad = d2l._hw_stats(times)  # median and MAD
    return dict(ms=ms, mad=mad)

def hw_h2d_bench(nbytes, pinned=True, direction='h2d', numa=None,
                 device=None, repeats=10, huge_pages=False):
    """Milliseconds per copy (median and MAD over repeats) and GB/s of
    nbytes between host memory, pinned or pageable, and GPU memory: host to
    device ('h2d') or back ('d2h'). CUDA events bracket enough back-to-back
    copies for a few milliseconds; a pageable copy blocks the host, a
    pinned one is queued. The host buffer lives on NUMA node numa if given,
    in 2 MiB pages if huge_pages.

    Defined in :numref:`sec_lm_memory_tiers`"""
    host, gpu = d2l._copy_buffers(nbytes, pinned, numa, device, huge_pages)
    src, dst = (host, gpu) if direction == 'h2d' else (gpu, host)
    copies = d2l._copies_per_timing(nbytes)
    start, stop = (torch.cuda.Event(enable_timing=True) for _ in range(2))
    ms = []
    with torch.cuda.device(gpu.device):
        for _ in range(repeats + 1):  # the first round warms up
            start.record()
            for _ in range(copies):
                dst.copy_(src, non_blocking=pinned)
            stop.record()
            stop.synchronize()
            ms.append(start.elapsed_time(stop) / copies)
    med, mad = d2l._hw_stats(ms[1:])
    return dict(ms=med, mad=mad, gbs=nbytes / med / 1e6)

def fit_alpha_beta(sizes, times, weights=None):
    """Fit t = alpha + s / beta to transfer times (seconds) at sizes
    (bytes) by weighted least squares, weights 1 / t^2 by default (each
    point's relative error counts alike). Returns (alpha, beta, cov) with
    alpha in seconds, beta in bytes per second and cov the 2 x 2
    covariance of (alpha, beta).

    Defined in :numref:`sec_lm_memory_tiers`"""
    s = np.asarray(sizes, dtype=float)
    t = np.asarray(times, dtype=float)
    w = 1 / t**2 if weights is None else np.asarray(weights, dtype=float)
    X = np.stack([np.ones_like(s), s], axis=1)  # columns: alpha, 1 / beta
    XtW = X.T * w
    A = np.linalg.inv(XtW @ X)
    alpha, g = A @ (XtW @ t)
    r = t - X @ np.array([alpha, g])
    dof = max(len(t) - 2, 1)
    cov_ag = A * (w @ r**2) / dof
    J = np.array([[1.0, 0.0], [0.0, -1 / g**2]])  # d(alpha, beta)/d(alpha, g)
    return float(alpha), float(1 / g), J @ cov_ag @ J.T

def offload_breakeven(p_eff, link_bw, bytes_per_param_per_dir=2):
    """T_link, the tokens per GPU and step above which the transfers of an
    offloaded optimizer (bytes_per_param_per_dir down and as many up per
    parameter, full duplex) hide behind the step's 6 N T FLOPs:
    6 N T / p_eff >= b N / link_bw, so T >= p_eff b / (6 link_bw).

    Defined in :numref:`sec_lm_memory_tiers`"""
    return p_eff * bytes_per_param_per_dir / (6 * link_bw)

def kv_load_vs_recompute(cfg, n, link_bw, p_eff, chip=None,
                         alpha=0.0, n_max=None, beta_eff=None):
    """Seconds to load the KV cache of prefixes of n tokens over a link
    (alpha + n k_KV / link_bw) and to recompute them (ServingModel's
    prefill_time at p_eff and the memory rate beta_eff, by default the
    chip's datasheet; chip None: FLOPs alone), and the crossover: the
    shortest prefix up to n_max (the model's context) from which loading
    is at least as fast (inf if none).

    Defined in :numref:`sec_lm_memory_tiers`"""
    chip = d2l._flops_only_chip(p_eff) if chip is None else chip
    m = d2l.ServingModel(cfg, chip, calib=dict(
        P_eff_bf16=p_eff, beta_eff=beta_eff or chip.mem_bw_tbs * 1e12))
    k = m.kv_bytes_per_token()  # bytes of K and V per token, all layers
    n_max = n_max or cfg.max_position_embeddings

    def times(x):
        return alpha + x * k / link_bw, np.array([m.prefill_time(int(v))
                                                  for v in x])
    grid = np.unique(np.geomspace(1, n_max, 400).astype(int))
    load, recompute = times(grid)
    loses = np.flatnonzero(load > recompute)  # the last prefix it loses at
    first = 0 if len(loses) == 0 else loses[-1] + 1
    load_n, recompute_n = times(np.asarray(n))
    return dict(n=np.asarray(n), load_s=load_n, recompute_s=recompute_n,
                k_kv=k, n_max=n_max,
                crossover=grid[first] if first < len(grid) else np.inf)

def nccl_busbw_factor(op, k):
    """Bus bandwidth over algorithm bandwidth (nccl-tests' convention): the
    bytes each GPU's link carries per byte of the message.

    Defined in :numref:`sec_lm_server_paths`"""
    op = op.replace('_', '')
    if op == 'allreduce':
        return 2 * (k - 1) / k  # reduce-scatter, then all-gather
    if op in ('allgather', 'reducescatter', 'alltoall'):
        return (k - 1) / k
    if op in ('broadcast', 'reduce'):
        return 1.0
    raise ValueError(f'unknown collective {op!r}')

def coll_time(op, S, k, alpha, beta, algo='ring'):
    """Seconds for a collective of S bytes per GPU on k GPUs, alpha (s)
    per step, beta (bytes/s) per link and direction: a ring (direct for
    all-to-all on a crossbar), or algo='tree' for the binary-tree
    all-reduce (reduce up, broadcast down, the whole message per hop).

    Defined in :numref:`sec_lm_server_paths`"""
    op = op.replace('_', '')
    if op not in ('allreduce', 'allgather', 'reducescatter', 'alltoall'):
        raise ValueError(f'coll_time does not model {op!r}')
    if algo == 'tree' and op == 'allreduce':
        return 2 * math.ceil(math.log2(k)) * (alpha + S / beta)
    if algo != 'ring':
        raise ValueError(f'no {algo} {op} in this model')
    steps = 2 * (k - 1) if op == 'allreduce' else k - 1
    return steps * (alpha + S / (k * beta))  # S / k bytes per step

def tree_link_loads(k, groups, pattern, S=1.0, staged=False):
    """Bytes on each link of a two-level tree, its busier direction, when
    k GPUs (groups: the GPUs below each uplink) run pattern on S bytes per
    GPU: 'alltoall' (S / k to every other GPU) or 'allreduce' (a ring in
    the groups' order, 2 (k - 1) / k S over each ring edge). Keys 'GPU i'
    and 'uplink g'. staged: every byte passes through host memory above
    the uplinks, even between two GPUs of one group.

    Defined in :numref:`sec_lm_server_paths`"""
    group = {i: gi for gi, grp in enumerate(groups) for i in grp}
    assert len(group) == k, 'groups must hold the k GPUs once each'
    if pattern == 'alltoall':
        flows = [(i, j, S / k) for i in group for j in group if i != j]
    elif pattern == 'allreduce':
        ring = [i for grp in groups for i in grp]
        flows = [(i, j, 2 * (k - 1) / k * S)
                 for i, j in zip(ring, ring[1:] + ring[:1])]
    else:
        raise ValueError(f'unknown pattern {pattern!r}')
    load = {}  # (link, direction): bytes
    for i, j, b in flows:
        hops = [(f'GPU {i}', 'up'), (f'GPU {j}', 'down')]
        if staged or group[i] != group[j]:
            hops += [(f'uplink {group[i]}', 'up'),
                     (f'uplink {group[j]}', 'down')]
        for hop in hops:
            load[hop] = load.get(hop, 0) + b
    out = {}
    for (link, _), b in load.items():
        out[link] = max(out.get(link, 0), b)
    return out

def pattern_time(k, groups, p, beta, beta_u, S=1.0, staged=False):
    """Seconds of pattern p on the two-level tree: the busiest link's
    bytes over that link's rate (bytes/s: beta for a GPU's link, beta_u
    for an uplink).

    Defined in :numref:`sec_lm_server_paths`"""
    loads = tree_link_loads(k, groups, p, S, staged)
    return max(b / (beta_u if link.startswith('uplink') else beta)
               for link, b in loads.items())

def a2a_busbw_ratio(k, groups, beta, beta_u, staged=False):
    """Predicted bus bandwidth of the all-to-all over the ring
    all-reduce's on a two-level tree (busbw = factor x S / time).

    Defined in :numref:`sec_lm_server_paths`"""
    busbw = {p: nccl_busbw_factor(p, k)
             / pattern_time(k, groups, p, beta, beta_u, staged=staged)
             for p in ('alltoall', 'allreduce')}
    return busbw['alltoall'] / busbw['allreduce']

def fat_tree(radix, tiers, oversub=1.0, rails=1):
    """A two-tier (leaf-spine) or three-tier fat tree of radix-port
    switches whose edge switches have `down` endpoint ports and
    up = down / oversub uplinks; rails > 1 wires NIC i of each host to
    rail i's edge switch of its group. Counts and the graph (networkx).

    Defined in :numref:`sec_lm_networks`"""
    import networkx as nx
    r, G = radix, nx.Graph()
    up = int(r // (1 + oversub))
    down = int(round(oversub * up))
    if tiers == 2:  # every leaf has one link to each spine
        edge = [f'leaf{i}' for i in range(r)]
        G.add_edges_from((l, f'spine{j}') for l in edge for j in range(up))
    else:  # r pods: r/2 edge and `up` aggregation switches, r/2 cores each
        edge = [f'edge{p}.{i}' for p in range(r) for i in range(r // 2)]
        G.add_edges_from((e, f'agg{e[4:].split(".")[0]}.{j}')
                         for e in edge for j in range(up))
        G.add_edges_from((f'agg{p}.{j}', f'core{j}.{c}') for p in range(r)
                         for j in range(up) for c in range(r // 2))
    attach = {}  # endpoint -> its edge switch
    for g in range(len(edge) // rails):
        for h in range(down):
            for nic in range(rails):
                attach[f'host{g}.{h}/{nic}'] = edge[g * rails + nic]
    G.add_edges_from(attach.items())
    return dict(endpoints=len(attach), hosts=len(attach) // rails,
                switches=G.number_of_nodes() - len(attach),
                links=G.number_of_edges(), down=down, up=up, graph=G,
                edge_switches=edge, attach=attach)

def layer_params(cfg):
    """Matmul parameters of one transformer layer that a token uses: the
    attention projections plus the MLP (K experts of width d_ff for a
    mixture of experts).

    Defined in :numref:`sec_lm_networks`"""
    d, d_h = cfg.hidden_size, cfg.head_dim
    attn = 2 * d * d_h * (cfg.num_attention_heads + cfg.num_key_value_heads)
    K = getattr(cfg, 'num_experts_per_tok', 0) or 1
    d_ff = (cfg.moe_intermediate_size if K > 1 else cfg.intermediate_size)
    return attn + K * 3 * d * d_ff

def axis_ratio(axis, cfg, link_ridge, b, t, e, n_stage, b_g, T, k):
    """D1: communication over compute time of one parallel axis ('tp',
    'ep', 'pp', 'dp') on a link of ridge R = P_eff / beta (FLOP per byte),
    with no overlap and attention FLOPs ignored; NaN for 'ep' of a dense
    model.

    Defined in :numref:`sec_lm_networks`"""
    d, R, N_layer = cfg.hidden_size, link_ridge, layer_params(cfg)
    d_ff = getattr(cfg, 'moe_intermediate_size', None) or math.nan
    N_stage = cfg.num_hidden_layers * N_layer / n_stage
    rho = {'tp': lambda: 4 / 3 * (t - 1) * d * b / N_layer * R,
           'ep': lambda: 2 * b * (1 - 1 / e) / (9 * d_ff) * R,
           'pp': lambda: d * b / (3 * N_stage) * R,
           'dp': lambda: b_g / (3 * T) * R * (k - 1) / k}
    return rho[axis]()

AXIS_OVERLAP = {'tp': 0.0, 'ep': 0.5, 'pp': 0.9, 'dp': 0.9}

def layout_fit(cfg, system, layout, tokens_per_step, p_eff=None, eps=0.15,
               overlap=AXIS_OVERLAP, b=2, b_g=2, mfu=1.0):  #@save
    """Per axis of a layout (degrees t, e, p, k) on a systems-table row:
    the link it lands on (scale-up when the ranks it spans fit in one
    domain), that link's ridge, GB per chip and step, the ratio after
    overlap and whether it fits; attrs: the training state per chip.
    P_eff is p_eff, else mfu times the chip's dense bf16 peak.

    Defined in :numref:`sec_lm_networks`"""
    P = p_eff or mfu * system.p16_tflops * 1e12
    t, e, p, k = (layout[a] for a in 'tepk')
    degree = {'tp': t, 'ep': e, 'pp': p, 'dp': k}
    span = {'tp': t, 'ep': t * e, 'pp': t * e * p, 'dp': t * p * k}
    par = dict(b=b, b_g=b_g, t=t, e=e, n_stage=p, T=tokens_per_step / k, k=k)
    mem = d2l.state_per_chip(cfg, system, layout)
    t_c = (6 * cfg.num_hidden_layers * layer_params(cfg) * tokens_per_step
           / (t * p * k * P))  # compute seconds per chip and step
    t_axis = {'ep': t_c * d2l.expert_flop_share(cfg)}  # ep: expert FLOPs
    held = mem['n_held'] * t * p / (cfg.num_hidden_layers * layer_params(cfg))
    rows = {}
    for axis in (a for a in degree if degree[a] > 1):
        up = span[axis] <= system.domain_chips
        beta = 1e9 * (system.up_gbs_dir if up
                      else system.scaleout_gbs_per_chip)
        rho = axis_ratio(axis, cfg, P / beta, **par) * (
            held if axis == 'dp' else 1)
        rows[axis] = dict(degree=degree[axis], ridge=P / beta,
                          link='scale-up' if up else 'scale-out',
                          gb_per_step=rho * t_axis.get(axis, t_c) * beta / 1e9,
                          ratio=rho * (1 - overlap[axis]))
    fit = pd.DataFrame.from_dict(rows, orient='index')
    fit['fit'] = fit.ratio <= eps
    fit.attrs.update(mem, eps=eps)
    return fit

def layout_for(cfg, system, degrees, job_chips, tokens_per_step, **kw):
    """The usual placement of a job of job_chips chips (all the system's
    chips when it has no scale-out network): the largest power-of-two t,
    then e, up to degrees and one domain, whose ratio fits (layout_fit
    with the keywords kw); p pipeline stages; data parallelism over the
    rest.

    Defined in :numref:`sec_lm_networks`"""
    n = job_chips if system.has_scaleout else int(system.chips)
    D = int(min(system.domain_chips, n))

    def place(t, e):
        p = min(degrees['p'], n // (t * e))
        return dict(t=t, e=e, p=p, k=n // (t * p))

    def fits(axis, t, e):
        return layout_fit(cfg, system, place(t, e), tokens_per_step,
                          **kw).fit[axis]

    powers = lambda cap: [2**i for i in range(int(math.log2(cap)), 0, -1)]
    t = next((t for t in powers(min(degrees['t'], D)) if fits('tp', t, 1)), 1)
    e = next((e for e in powers(min(degrees['e'], D // t))
              if fits('ep', t, e)), 1)
    return place(t, e)

def diloco_wan_bandwidth(n_params, bytes_per_param, h_steps, t_step_s):
    """Bytes/s a WAN must carry to hide one synchronization of the
    parameters every h_steps steps of t_step_s seconds.

    Defined in :numref:`sec_lm_networks`"""
    return n_params * bytes_per_param / (h_steps * t_step_s)

def ring_allreduce_time(S, G, alpha, beta):
    """Seconds of a ring all-reduce of S bytes on G ranks: 2 (G - 1)
    steps, each sending S / G bytes over a link of beta bytes/s and paying
    alpha seconds of latency.

    Defined in :numref:`sec_lm_collectives`"""
    return 2 * (G - 1) * (alpha + S / (G * beta))

def tree_allreduce_time(S, n, g, a_in, a_out, beta, pipelined=True):
    """Seconds of a double-binary-tree all-reduce of S bytes across n
    nodes whose g GPUs form a chain: a leaf is g - 1 hops (latency a_in)
    plus ceil(log2 n) hops (a_out) from its root, paid up and down.
    Pipelined in small chunks, every rank sends 2 S bytes in all;
    unpipelined (one tree), every hop carries the whole message.

    Defined in :numref:`sec_lm_collectives`"""
    up = math.ceil(math.log2(n))
    latency = (g - 1) * a_in + up * a_out
    if pipelined:
        return 2 * latency + 2 * S / beta
    return 2 * (latency + (g - 1 + up) * S / beta)

def hier_allreduce_time(S, n, g, a_in, b_in, a_out, b_out, rails=1):
    """Seconds of a hierarchical all-reduce on n nodes of g GPUs:
    reduce-scatter in the node, a ring all-reduce of each GPU's shard of
    S / g across the nodes, all-gather in the node. The g shards leave a
    node on its `rails` NICs (rails = g: one per GPU), each at b_out
    min(rails, g) / g.

    Defined in :numref:`sec_lm_collectives`"""
    intra = 2 * (g - 1) * (a_in + S / (g * b_in))  # both intra stages
    b_shard = b_out * min(rails, g) / g
    return intra + ring_allreduce_time(S / g, n, a_out, b_shard)

def sharp_allreduce_time(S, alpha, beta):
    """Seconds of an in-network all-reduce (SHARP, NVLS): each GPU sends S
    once to the switches and receives the reduced S once.

    Defined in :numref:`sec_lm_collectives`"""
    return alpha + S / beta

def double_binary_tree(G):
    """NCCL's two trees over G ranks as {rank: parent} dicts (None at the
    root). In the first, the odd ranks are leaves; the second mirrors it
    (even G) or shifts it by one (odd G), so that every leaf of one tree
    is interior in the other.

    Defined in :numref:`sec_lm_collectives`"""
    def tree(rank_at):  # rank_at(position) -> rank
        parent = {}
        for p in range(G):
            bit = p & -p  # the lowest set bit: p's level in the tree
            up = None if p == 0 else (p ^ bit) | (bit << 1)
            if up is not None and up >= G:
                up = p ^ bit
            parent[rank_at(p)] = None if up is None else rank_at(up)
        return parent
    second = (lambda p: G - 1 - p) if G % 2 == 0 else (lambda p: (p + 1) % G)
    return tree(lambda p: p), tree(second)

def sim_collective(topo, algo, S, chunks):
    """Seconds of an all-reduce of S bytes, simulated message by message.
    Every rank has a sending and a receiving port of topo['beta'] bytes/s;
    a port serves its waiting messages lowest chunk first, a message
    passes both ports at once and arrives topo['alpha'] s later. 'ring':
    2 (G - 1) steps of one S / G segment; 'tree': each half of S, cut into
    chunks, is reduced up one of the two trees and broadcast down it.

    Defined in :numref:`sec_lm_collectives`"""
    import heapq, itertools  # not in the d2l library preamble
    G, alpha, beta = topo['G'], topo['alpha'], topo['beta']
    Msg = collections.namedtuple('Msg', 'src dst nbytes chunk tag')
    tick, events, free, waiting = itertools.count(), [], {}, {}
    def at(t, *event):
        heapq.heappush(events, (t, next(tick), event))
    def serve(t, port):  # start the next waiting message if the port is idle
        if waiting.get(port) and free.get(port, 0.0) <= t:
            msg = heapq.heappop(waiting[port])[2]
            free[port] = t + msg.nbytes / beta
            at(free[port], 'port free', port, msg)
            if port[0] == 'out':  # cut-through: the receiver starts too
                offer(t, ('in', msg.dst), msg)
    def offer(t, port, msg):  # queue msg at port, ordered by its chunk
        heapq.heappush(waiting.setdefault(port, []),
                       (msg.chunk, next(tick), msg))
        serve(t, port)
    def send(t, *fields):  # fields: src, dst, nbytes, chunk, tag
        msg = Msg(*fields)
        offer(t, ('out', msg.src), msg)
    trees = double_binary_tree(G)
    kids = [{r: [c for c in tr if tr[c] == r] for r in tr} for tr in trees]
    def reduced(t, k, r, j):  # chunk j of tree k is summed at rank r
        for dst in kids[k][r] if trees[k][r] is None else [trees[k][r]]:
            send(t, r, dst, S / 2 / chunks, j,
                 (k, 'down' if trees[k][r] is None else 'up'))
    if algo == 'ring':
        for r in range(G):
            send(0.0, r, (r + 1) % G, S / G, 0, 0)  # tag: the step
    else:
        for j, k in itertools.product(range(chunks), range(2)):
            for r in trees[k]:
                if not kids[k][r]:  # a leaf starts chunk j up its tree
                    reduced(0.0, k, r, j)
    got, end = collections.Counter(), 0.0
    while events:
        t, _, (kind, port, msg) = heapq.heappop(events)
        if kind == 'port free':
            serve(t, port)
            if port[0] == 'in':
                end = max(end, t + alpha)
                at(t + alpha, 'arrived', None, msg)
            continue
        if algo == 'ring':  # tag: the step
            if msg.tag + 1 < 2 * (G - 1):
                send(t, msg.dst, (msg.dst + 1) % G, msg.nbytes, msg.chunk,
                     msg.tag + 1)
            continue
        k, way = msg.tag  # tree k, 'up' or 'down'
        if way == 'down':
            for c in kids[k][msg.dst]:
                send(t, msg.dst, c, msg.nbytes, msg.chunk, msg.tag)
        else:
            got[k, msg.dst, msg.chunk] += 1
            if got[k, msg.dst, msg.chunk] == len(kids[k][msg.dst]):
                reduced(t, k, msg.dst, msg.chunk)
    return end

def hier_allreduce(tensor, intra_group, inter_group):
    """All-reduce tensor in place over every rank in three stages:
    reduce-scatter among the ranks of intra_group, all-reduce of each
    rank's shard across inter_group, all-gather in intra_group. The groups
    may use different backends: a CUDA tensor crosses a gloo group through
    a pinned host copy. tensor.numel() must be a multiple of the size of
    intra_group.

    Defined in :numref:`sec_lm_collectives`"""
    from torch import distributed as dist  # not in the d2l preamble
    flat = tensor.view(-1)
    shard = flat.new_empty(flat.numel() // dist.get_world_size(intra_group))
    dist.reduce_scatter_tensor(shard, flat, group=intra_group)
    if shard.is_cuda and dist.get_backend(inter_group) == 'gloo':
        host = torch.empty(shard.shape, dtype=shard.dtype, pin_memory=True)
        host.copy_(shard)
        dist.all_reduce(host, group=inter_group)
        shard.copy_(host)
    else:
        dist.all_reduce(shard, group=inter_group)
    dist.all_gather_into_tensor(flat, shard, group=intra_group)
    return tensor

DVFSFit = collections.namedtuple('DVFSFit', [
    'P_s', 'k', 'f_star', 'f_min', 'f_knee', 'knee_x', 'step', 'edge',
    'locks', 'clocks', 'power', 'rate', 'left_out', 'spread', 'source',
    'a100'])

def dvfs_fit(log):
    """Fit P(f) = P_s + k f^3 (f in GHz: the clock each window ran at, one
    point per clock) by least squares to the locked-clock windows of the
    compute-bound workload; f* = (P_s / (2k))^(1/3) maximizes the work
    per joule. Locks whose rate says they ran at another clock than the
    one reported are left out (left_out: lock -> clock as run). f_min is
    the lock of least energy per unit of work, f_knee where the power
    curve steepens (knee_x: by how much), step the sweep's largest step,
    edge whether f_min is the lowest lock, spread the largest relative
    spread of a window's power across processes (NaN: one run).

    Defined in :numref:`sec_lm_energy_cost`"""
    s = log[(log.kind == 'clock') & log.workload.str.startswith('matmul')]
    s = s.sort_values('setting')
    lock = s.setting.to_numpy() / 1e3
    i = int(np.argmin(s.power_w.to_numpy() / s.rate.to_numpy()))  # J/FLOP
    left_out = d2l._misreported_locks(s)  # {lock: clock its rate implies}
    s = s[~np.isin(s.setting.to_numpy() / 1e3, list(left_out))]
    f, P = d2l._clock_points(s)  # one point per clock as run: GHz, W
    A = np.stack([np.ones_like(f), f**3], axis=1)  # P is linear in 1, f^3
    (P_s, k), *_ = np.linalg.lstsq(A, P, rcond=None)
    spread = (log.attrs.get('spread') or {}).get('power_w')
    spread = (np.nanmax(np.asarray(spread, float)[s.index]) if spread
              else 0.0 if log.attrs.get('n_proc', 1) > 1 else math.nan)
    return DVFSFit(P_s, k, (P_s / (2 * k)) ** (1 / 3), lock[i],
                   *d2l._power_knee(f, P),
                   np.diff(lock).max() if len(lock) > 1 else math.nan,
                   i == 0, s.setting.to_numpy() / 1e3,
                   s.sm_mhz.to_numpy() / 1e3, s.power_w.to_numpy(),
                   s.rate.to_numpy(), left_out, spread,
                   log.attrs.get('source', ''), log.attrs.get('a100'))

def hw_clock_sweep(clocks, workloads, device=0):
    """Board power, clocks and work rate of each named workload with the SM
    clock locked at each of clocks (MHz) on visible GPU `device`; needs
    permission to lock clocks (sudo -n inside the regeneration).

    Defined in :numref:`sec_lm_energy_cost`"""
    smi = d2l.hw_smi_card(device)  # nvidia-smi on that card, guarded
    if smi('-lgc', f'{clocks[0]},{clocks[0]}').refused:
        raise PermissionError('the driver refused to lock the SM clock')
    rows = []
    try:
        for f in clocks:
            smi('-lgc', f'{f},{f}')  # minimum = maximum: the clock is pinned
            rows += d2l._sweep_rows('clock', f, workloads, smi)
    finally:
        smi.restore('-rgc')  # back to the default clocks, or say it failed
    return pd.DataFrame(rows)

def energy_per_token(power_trace, tokens):
    """Joules per token of a traced window: the trapezoid integral of the
    samples' power (W) over their times (s), divided by the tokens
    produced over the trace's span.

    Defined in :numref:`sec_lm_energy_cost`"""
    t = np.array([s['t'] for s in power_trace])
    P = np.array([s['power_w'] for s in power_trace])
    return float(np.sum((P[1:] + P[:-1]) / 2 * np.diff(t))) / tokens

def cost_per_mtok_train(price_gpu_h, flops_per_token, p_peak, mfu,
                        goodput=1.0):
    """Dollars per million training tokens: a GPU-second costs
    price_gpu_h / 3600 and trains mfu * goodput * p_peak / flops_per_token
    tokens.

    Defined in :numref:`sec_lm_energy_cost`"""
    return 1e6 * price_gpu_h / 3600 * flops_per_token / (
        mfu * goodput * p_peak)

def cost_per_mtok_serve(price_gpu_h, tps_per_gpu, utilization=1.0):  #@save
    """Dollars per million served tokens at tps_per_gpu tokens/s while the
    GPU serves a fraction utilization of the hours it is paid for."""
    return 1e6 * price_gpu_h / 3600 / (tps_per_gpu * utilization)

def owned_vs_rented(capex, life_h, power_kw, pue, elec_per_kwh, ops_per_h,
                    rent_per_h):
    """Owning costs h_own per hour, used or not (capex over its life, power
    at the wall, operations); renting costs rent_per_h per used hour. Owning
    is cheaper above the utilization u* = h_own / rent_per_h.
    owned_per_used_h is h_own, the cost of an owned hour of work at full
    use (h_own / u at utilization u).

    Defined in :numref:`sec_lm_energy_cost`"""
    h_own = capex / life_h + power_kw * pue * elec_per_kwh + ops_per_h
    return dict(owned_per_used_h=h_own, u_star=h_own / rent_per_h)

def train_batch_ch13(net, X, y, loss, trainer, devices):
    """Train for a minibatch with multiple GPUs (defined in Chapter 13).

    Defined in :numref:`sec_image_augmentation`"""
    if isinstance(X, list):
        # Required for BERT fine-tuning (to be covered later)
        X = [x.to(devices[0]) for x in X]
    else:
        X = X.to(devices[0])
    y = y.to(devices[0])
    net.train()
    trainer.zero_grad()
    pred = net(X)
    l = loss(pred, y)
    l.sum().backward()
    trainer.step()
    train_loss_sum = l.sum() if l.numel() > 1 else l * y.numel()
    train_acc_sum = d2l.accuracy(pred, y)
    return train_loss_sum, train_acc_sum

def train_ch13(net, train_iter, test_iter, loss, trainer, num_epochs,
               devices=d2l.try_all_gpus()):
    """Train a model with multiple GPUs (defined in Chapter 13).

    Defined in :numref:`sec_image_augmentation`"""
    timer, num_batches = d2l.Timer(), len(train_iter)
    animator = d2l.Animator(xlabel='epoch', xlim=[1, num_epochs], ylim=[0, 1],
                            legend=['train loss', 'train acc', 'test acc'])
    net = nn.DataParallel(net, device_ids=devices).to(devices[0])
    for epoch in range(num_epochs):
        # Sum of training loss, sum of training accuracy, no. of examples,
        # no. of examples
        metric = d2l.Accumulator(4)
        for i, (features, labels) in enumerate(train_iter):
            timer.start()
            l, acc = train_batch_ch13(
                net, features, labels, loss, trainer, devices)
            metric.add(l, acc, labels.shape[0], labels.numel())
            timer.stop()
            if (i + 1) % (num_batches // 5) == 0 or i == num_batches - 1:
                animator.add(epoch + (i + 1) / num_batches,
                             (metric[0] / metric[2], metric[1] / metric[3],
                              None))
        test_acc = d2l.evaluate_accuracy_gpu(net, test_iter)
        animator.add(epoch + 1, (None, None, test_acc))
    print(f'loss {metric[0] / metric[2]:.3f}, train acc '
          f'{metric[1] / metric[3]:.3f}, test acc {test_acc:.3f}')
    print(f'{metric[2] * num_epochs / timer.sum():.1f} examples/sec on '
          f'{str(devices)}')

